package main

import (
    "fmt"
    "go/ast"
    "go/importer"
    "go/parser"
    "go/token"
    "go/types"
    "io"
    "os"
    "os/exec"
    "encoding/json"
    "strings"
)

type GoListPkg struct {
    Dir string
    ImportPath string
    Name string
    GoFiles []string
    Export string
    Deps []string
}

func main() {
    // Use go list to get all packages with export data
    cmd := exec.Command("go", "list", "-json", "-export", "-e", "-deps", "./...")
    cmd.Dir = "/tmp/testpkg"
    out, err := cmd.CombinedOutput()
    if err != nil {
        fmt.Fprintf(os.Stderr, "go list error: %v\n%s\n", err, out)
    }

    // Parse all JSON objects from output
    exportMap := make(map[string]string) // importPath -> exportFile

    dec := json.NewDecoder(strings.NewReader(string(out)))
    for {
        var pkg GoListPkg
        if err := dec.Decode(&pkg); err != nil {
            break
        }
        if pkg.Export != "" {
            exportMap[pkg.ImportPath] = pkg.Export
            fmt.Printf("Package %s -> %s\n", pkg.ImportPath, pkg.Export)
        }
    }

    // Now try to type check
    fset := token.NewFileSet()
    f, err := parser.ParseFile(fset, "/tmp/testpkg/pkg/main.go", nil, 0)
    if err != nil {
        fmt.Fprintf(os.Stderr, "parse error: %v\n", err)
        os.Exit(1)
    }

    lookup := func(path string) (io.ReadCloser, error) {
        if exportFile, ok := exportMap[path]; ok {
            return os.Open(exportFile)
        }
        return nil, fmt.Errorf("not found: %s", path)
    }

    conf := types.Config{
        Importer: importer.ForCompiler(fset, "gc", lookup),
    }

    info := &types.Info{
        Types: make(map[ast.Expr]types.TypeAndValue),
        Defs:  make(map[*ast.Ident]types.Object),
        Uses:  make(map[*ast.Ident]types.Object),
    }

    typedPkg, err := conf.Check("example.com/testpkg/pkg", fset, []*ast.File{f}, info)
    if err != nil {
        fmt.Fprintf(os.Stderr, "type check error: %v\n", err)
        os.Exit(1)
    }

    fmt.Printf("\nPackage: %s\n", typedPkg.Path())

    // Walk the AST to find all call expressions
    ast.Inspect(f, func(n ast.Node) bool {
        if call, ok := n.(*ast.CallExpr); ok {
            if tv, ok := info.Types[call]; ok {
                fmt.Printf("Call: %v -> %v\n", call, tv.Type)
            }
        }
        return true
    })
}
EOF

