	localPath := filepath.Join(dir, ".wrapcheck.yaml")
	if cfg, err := parseConfigFile(localPath); err == nil {
		return cfg, nil
	}

	// Try home directory
	home, err := os.UserHomeDir()
	if err == nil {
		homePath := filepath.Join(home, ".wrapcheck.yaml")
		if cfg, err := parseConfigFile(homePath); err == nil {
			return cfg, nil
		}
	}

	return &WrapcheckConfig{}, nil
}

// parseConfigFile parses a .wrapcheck.yaml file.
// This is a simple hand-written parser for the YAML subset used by wrapcheck.
func parseConfigFile(path string) (*WrapcheckConfig, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	return parseConfig(f)
}

// parseConfig parses wrapcheck config from a reader.
// This is a simple YAML parser that handles the specific format used.
func parseConfig(r io.Reader) (*WrapcheckConfig, error) {
	cfg := &WrapcheckConfig{}
	scanner := bufio.NewScanner(r)

	var currentKey string
	var inList bool

	for scanner.Scan() {
		line := scanner.Text()

		// Skip empty lines and comments
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}

		// Check if this is a key-value pair (not indented)
		if !strings.HasPrefix(line, " ") && !strings.HasPrefix(line, "\t") {
			inList = false
			if idx := strings.Index(trimmed, ":"); idx >= 0 {
				key := strings.TrimSpace(trimmed[:idx])
				value := strings.TrimSpace(trimmed[idx+1:])

				currentKey = key

				// Handle inline list like "key: []"
				if value == "[]" {
					setListField(cfg, key, []string{})
					inList = false
					continue
				}

				// Handle boolean
				if value == "true" || value == "false" {
					setBoolField(cfg, key, value == "true")
					continue
				}

				// Handle inline list like "key: [a, b, c]"
				if strings.HasPrefix(value, "[") && strings.HasSuffix(value, "]") {
					inner := value[1 : len(value)-1]
					items := parseInlineList(inner)
					setListField(cfg, key, items)
					inList = false
					continue
				}

				if value == "" {
					inList = true
				}
			}
		} else {
			// This is an indented line - part of a list
			if inList && strings.HasPrefix(trimmed, "- ") {
				item := strings.TrimPrefix(trimmed, "- ")
				// Handle quoted strings
				item = unquoteYAML(item)
				appendListField(cfg, currentKey, item)
			}
		}
	}

	return cfg, scanner.Err()
}

func parseInlineList(s string) []string {
	if s == "" {
		return []string{}
	}
	parts := strings.Split(s, ",")
	result := make([]string, 0, len(parts))
	for _, p := range parts {
		p = strings.TrimSpace(p)
		p = unquoteYAML(p)
		if p != "" {
			result = append(result, p)
		}
	}
	return result
}

func unquoteYAML(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= 2 {
		if (s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '\'' && s[len(s)-1] == '\'') {
			return s[1 : len(s)-1]
		}
	}
	return s
}

func setBoolField(cfg *WrapcheckConfig, key string, value bool) {
	switch key {
	case "reportInternalErrors":
		cfg.ReportInternalErrors = value
	}
}

func setListField(cfg *WrapcheckConfig, key string, value []string) {
	switch key {
	case "ignoreSigs":
		cfg.IgnoreSigs = value
	case "extraIgnoreSigs":
		cfg.ExtraIgnoreSigs = value
	case "ignoreSigRegexps":
		cfg.IgnoreSigRegexps = value
	case "ignorePackageGlobs":
		cfg.IgnorePackageGlobs = value
	case "ignoreInterfaceRegexps":
		cfg.IgnoreInterfaceRegexps = value
	}
}

func appendListField(cfg *WrapcheckConfig, key string, value string) {
	switch key {
	case "ignoreSigs":
		cfg.IgnoreSigs = append(cfg.IgnoreSigs, value)
	case "extraIgnoreSigs":
		cfg.ExtraIgnoreSigs = append(cfg.ExtraIgnoreSigs, value)
	case "ignoreSigRegexps":
		cfg.IgnoreSigRegexps = append(cfg.IgnoreSigRegexps, value)
	case "ignorePackageGlobs":
		cfg.IgnorePackageGlobs = append(cfg.IgnorePackageGlobs, value)
	case "ignoreInterfaceRegexps":
		cfg.IgnoreInterfaceRegexps = append(cfg.IgnoreInterfaceRegexps, value)
	}
}

// GetIgnoreSigs returns the effective list of signature substrings to ignore.
func (cfg *WrapcheckConfig) GetIgnoreSigs() []string {
	base := DefaultIgnoreSigs
	if cfg.IgnoreSigs != nil {
		base = cfg.IgnoreSigs
	}
	if len(cfg.ExtraIgnoreSigs) > 0 {
		result := make([]string, len(base)+len(cfg.ExtraIgnoreSigs))
		copy(result, base)
		copy(result[len(base):], cfg.ExtraIgnoreSigs)
		return result
	}
	return base
}
