package wrapcheck

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"path"
	"regexp"
	"strings"
)

// Diagnostic represents a wrapcheck finding.
type Diagnostic struct {
	Pos     token.Position
	Message string
}

// Analyzer runs the wrapcheck analysis on a package.
type Analyzer struct {
	Config     *WrapcheckConfig
	PkgPath    string
	Fset       *token.FileSet
	Files      []*ast.File
	TypesInfo  *types.Info
	Pkg        *types.Package
	Diagnostics []Diagnostic
}

// Run executes the wrapcheck analysis.
func (a *Analyzer) Run() {
	cfg := a.Config
	if cfg == nil {
		cfg = &WrapcheckConfig{}
	}

	// Compile ignore signature regexps
	var sigRegexps []*regexp.Regexp
	for _, pattern := range cfg.IgnoreSigRegexps {
		re, err := regexp.Compile(pattern)
		if err == nil {
			sigRegexps = append(sigRegexps, re)
		}
	}

	// Compile interface regexps
	var ifaceRegexps []*regexp.Regexp
	for _, pattern := range cfg.IgnoreInterfaceRegexps {
		re, err := regexp.Compile(pattern)
		if err == nil {
			ifaceRegexps = append(ifaceRegexps, re)
		}
	}

	ignoreSigs := cfg.GetIgnoreSigs()

	// Walk all files
	for _, file := range a.Files {
		ast.Inspect(file, func(n ast.Node) bool {
			// Look for return statements
			ret, ok := n.(*ast.ReturnStmt)
			if !ok {
				return true
			}

			// Check each returned expression
			for _, result := range ret.Results {
				a.checkReturn(result, cfg, ignoreSigs, sigRegexps, ifaceRegexps)
			}

			return true
		})
	}
}

// checkReturn checks if the returned expression is an unwrapped error from an external package.
func (a *Analyzer) checkReturn(expr ast.Expr, cfg *WrapcheckConfig, ignoreSigs []string, sigRegexps []*regexp.Regexp, ifaceRegexps []*regexp.Regexp) {
	// Must be a call expression
	callExpr, ok := expr.(*ast.CallExpr)
	if !ok {
		return
	}

	// Get the type of the call expression
	tv, ok := a.TypesInfo.Types[callExpr]
	if !ok {
		return
	}

	// Must return an error type
	if !isErrorType(tv.Type) {
		// Check if it's a multi-return function where one is error
		// But we only care about the last return value
		tuple, ok := tv.Type.(*types.Tuple)
		if !ok || tuple.Len() == 0 {
			return
		}
		// Check last element
		last := tuple.At(tuple.Len() - 1)
		if !isErrorType(last.Type()) {
			return
		}
	}

	// Get the function/method being called
	sel, isSel := callExpr.Fun.(*ast.SelectorExpr)
	ident, isIdent := callExpr.Fun.(*ast.Ident)

	// Get the callee object
	var calleeObj types.Object
	if isSel {
		if obj, ok := a.TypesInfo.Uses[sel.Sel]; ok {
			calleeObj = obj
		}
	} else if isIdent {
		if obj, ok := a.TypesInfo.Uses[ident]; ok {
			calleeObj = obj
		}
	}

	if calleeObj == nil {
		return
	}

	// Get the function signature string for checking
	funcSig := getFuncSignature(calleeObj, a.TypesInfo, callExpr)

	// Check ignoreSigs (substring match)
	for _, ignore := range ignoreSigs {
		if strings.Contains(funcSig, ignore) {
			return
		}
	}

	// Check ignoreSigRegexps
	for _, re := range sigRegexps {
		if re.MatchString(funcSig) {
			return
		}
	}

	// Check if caller function returns an interface type from an external package
	// Determine the package of the callee
	calleePkg := calleeObj.Pkg()

	// Check ignorePackageGlobs
	if calleePkg != nil {
		pkgPath := calleePkg.Path()
		for _, glob := range cfg.IgnorePackageGlobs {
			matched, err := path.Match(glob, pkgPath)
			if err == nil && matched {
				return
			}
		}
	}

	// Check if this is an interface method call
	// and handle ignoreInterfaceRegexps
	ifaceType, ifaceTypeName := getInterfaceType(callExpr, a.TypesInfo)

	if ifaceType != nil {
		// It's an interface call
		// Check if ignoreInterfaceRegexps matches
		if len(ifaceRegexps) > 0 {
			for _, re := range ifaceRegexps {
				if re.MatchString(ifaceTypeName) {
					// Matched - for local interfaces suppress, for external fall through
					if calleePkg != nil && calleePkg.Path() == a.PkgPath {
						return // Suppress local interface error
					}
					// For external interfaces, fall through to external check below
					goto checkExternal
				}
			}
			// No match - report "interface method should be wrapped"
			a.reportInterfaceError(callExpr, funcSig)
			return
		}
		// No ignoreInterfaceRegexps configured - report "interface method should be wrapped"
		a.reportInterfaceError(callExpr, funcSig)
		return
	}

checkExternal:
	// Not an interface call (or interface check was suppressed for external interface)
	// Check if it's from an external package
	if calleePkg == nil {
		return
	}

	pkgPath := calleePkg.Path()
	if pkgPath == a.PkgPath {
		// Same package
		if cfg.ReportInternalErrors {
			pos := a.Fset.Position(callExpr.Pos())
			a.Diagnostics = append(a.Diagnostics, Diagnostic{
				Pos:     pos,
				Message: fmt.Sprintf("package-internal error should be wrapped: sig: %s", funcSig),
			})
		}
		return
	}

	// External package - report error
	pos := a.Fset.Position(callExpr.Pos())
	a.Diagnostics = append(a.Diagnostics, Diagnostic{
		Pos:     pos,
		Message: fmt.Sprintf("error returned from external package is unwrapped: sig: %s", funcSig),
	})
}

func (a *Analyzer) reportInterfaceError(callExpr *ast.CallExpr, funcSig string) {
	pos := a.Fset.Position(callExpr.Pos())
	a.Diagnostics = append(a.Diagnostics, Diagnostic{
		Pos:     pos,
		Message: fmt.Sprintf("error returned from interface method should be wrapped: sig: %s", funcSig),
	})
}

// isErrorType checks if t is the error interface.
func isErrorType(t types.Type) bool {
	return t != nil && t.String() == "error"
}

// getInterfaceType returns the interface type if the call is a method call on an interface.
// Returns (ifaceType, ifaceTypeName) or (nil, "") if not an interface call.
func getInterfaceType(callExpr *ast.CallExpr, info *types.Info) (types.Type, string) {
	sel, ok := callExpr.Fun.(*ast.SelectorExpr)
	if !ok {
		return nil, ""
	}

	// Get the type of the receiver
	recvTV, ok := info.Types[sel.X]
	if !ok {
		return nil, ""
	}

	recvType := recvTV.Type
	// Dereference pointer
	if ptr, ok := recvType.(*types.Pointer); ok {
		recvType = ptr.Elem()
	}

	// Check if it's a named type that is an interface
	named, ok := recvType.(*types.Named)
	if !ok {
		// Could be a direct interface type
		if iface, ok := recvType.(*types.Interface); ok {
			return iface, ""
		}
		return nil, ""
	}

	underlying := named.Underlying()
	if _, ok := underlying.(*types.Interface); ok {
		// It's an interface type
		typeName := named.String() // full qualified name like "example.com/pkg.InterfaceName"
		return underlying, typeName
	}

	return nil, ""
}

// getFuncSignature returns the function signature string used for checking.
func getFuncSignature(obj types.Object, info *types.Info, callExpr *ast.CallExpr) string {
	// Check if this is a method call on an interface type
	sel, isSel := callExpr.Fun.(*ast.SelectorExpr)
	if isSel {
		recvTV, ok := info.Types[sel.X]
		if ok {
			recvType := recvTV.Type
			// Dereference pointer
			if ptr, ok := recvType.(*types.Pointer); ok {
				recvType = ptr.Elem()
			}
			// Check if receiver is an interface
			if named, ok := recvType.(*types.Named); ok {
				if _, ok := named.Underlying().(*types.Interface); ok {
					// Interface method call - format: "func (PkgPath.TypeName).MethodName(params) returns"
					fn, ok := obj.(*types.Func)
					if ok {
						sig := fn.Type().(*types.Signature)
						typeName := named.String()
						return formatInterfaceSig(typeName, fn.Name(), sig)
					}
				}
			}
		}
	}

	// Regular function/method call
	fn, ok := obj.(*types.Func)
	if !ok {
		return obj.String()
	}

	return formatFuncSig(fn)
}

// formatFuncSig formats a function signature in the style wrapcheck uses.
func formatFuncSig(fn *types.Func) string {
	sig := fn.Type().(*types.Signature)
	recv := sig.Recv()

	var sb strings.Builder
	sb.WriteString("func ")

	if recv != nil {
		// Method with receiver
		recvType := recv.Type()
		sb.WriteString("(")
		sb.WriteString(recvType.String())
		sb.WriteString(")")
		sb.WriteString(".")
		sb.WriteString(fn.Name())
	} else {
		// Regular function
		pkg := fn.Pkg()
		if pkg != nil {
			sb.WriteString(pkg.Path())
			sb.WriteString(".")
		}
		sb.WriteString(fn.Name())
	}

	sb.WriteString(formatParams(sig))
	sb.WriteString(" ")
	sb.WriteString(formatResults(sig))

	return strings.TrimRight(sb.String(), " ")
}

// formatInterfaceSig formats a method signature for an interface type.
func formatInterfaceSig(typeName, methodName string, sig *types.Signature) string {
	var sb strings.Builder
	sb.WriteString("func (")
	sb.WriteString(typeName)
	sb.WriteString(").")
	sb.WriteString(methodName)
	sb.WriteString(formatParams(sig))
	sb.WriteString(" ")
	sb.WriteString(formatResults(sig))
	return strings.TrimRight(sb.String(), " ")
}

// formatParams formats function parameters.
func formatParams(sig *types.Signature) string {
	params := sig.Params()
	if params.Len() == 0 {
		if sig.Variadic() {
			return "()"
		}
		return "()"
	}

	var parts []string
	for i := 0; i < params.Len(); i++ {
		p := params.At(i)
		name := p.Name()
		typeStr := types.TypeString(p.Type(), nil)

		// Handle variadic last param
		if sig.Variadic() && i == params.Len()-1 {
			// For variadic, the last param type is a slice, convert to ...T
			sliceType, ok := p.Type().(*types.Slice)
			if ok {
				elemStr := types.TypeString(sliceType.Elem(), nil)
				if name != "" {
					parts = append(parts, name+" ..."+elemStr)
				} else {
					parts = append(parts, "..."+elemStr)
				}
				continue
			}
		}

		if name != "" {
			parts = append(parts, name+" "+typeStr)
		} else {
			parts = append(parts, typeStr)
		}
	}

	return "(" + strings.Join(parts, ", ") + ")"
}

// formatResults formats function return types.
func formatResults(sig *types.Signature) string {
	results := sig.Results()
	if results.Len() == 0 {
		return ""
	}

	if results.Len() == 1 {
		r := results.At(0)
		name := r.Name()
		typeStr := types.TypeString(r.Type(), nil)
		if name != "" {
			return name + " " + typeStr
		}
		return typeStr
	}

	var parts []string
	for i := 0; i < results.Len(); i++ {
		r := results.At(i)
		name := r.Name()
		typeStr := types.TypeString(r.Type(), nil)
		if name != "" {
			parts = append(parts, name+" "+typeStr)
		} else {
			parts = append(parts, typeStr)
		}
	}
	return "(" + strings.Join(parts, ", ") + ")"
}
