// GoListPackage is the JSON output from go list.
type GoListPackage struct {
	Dir         string
	ImportPath  string
	Name        string
	GoFiles     []string
	TestGoFiles []string
	XTestGoFiles []string
	IgnoredGoFiles []string
	CgoFiles    []string
	Export      string
	Standard    bool
	Root        string
	Incomplete  bool
	Match       []string
	Errors      []GoListError
	DepsErrors  []GoListError
}

type GoListError struct {
	Pos string
	Err string
}

// Package holds the loaded package data.
type Package struct {
	importPath string
	fset       *token.FileSet
	files      []*ast.File
	typesInfo  *types.Info
	pkg        *types.Package
	hasErrors  bool
	errors     []string
}

// loadPackages loads packages using go list and parses/type-checks them.
func loadPackages(patterns []string, includeTests bool) ([]*Package, error) {
	// Run go list to get all packages (deps first)
	args := []string{"list", "-json", "-e", "-export", "-deps"}
	args = append(args, patterns...)

	cmd := exec.Command("go", args...)
	cmd.Stderr = os.Stderr
	out, err := cmd.Output()
	if err != nil {
		// Try to get more info
		if exitErr, ok := err.(*exec.ExitError); ok {
			_ = exitErr
		}
	}

	// Parse all packages from go list output
	allPkgs := make(map[string]*GoListPackage)
	var orderedPaths []string
	var matchedPkgs []string

	dec := json.NewDecoder(strings.NewReader(string(out)))
	for {
		var pkg GoListPackage
		if err := dec.Decode(&pkg); err != nil {
			break
		}
		allPkgs[pkg.ImportPath] = &pkg
		orderedPaths = append(orderedPaths, pkg.ImportPath)
		if len(pkg.Match) > 0 {
			matchedPkgs = append(matchedPkgs, pkg.ImportPath)
		}
	}

	if len(allPkgs) == 0 {
		return nil, fmt.Errorf("no packages found for %v", patterns)
	}

	// Build export map for importer
	exportMap := make(map[string]string)
	for path, pkg := range allPkgs {
		if pkg.Export != "" {
			exportMap[path] = pkg.Export
		}
	}

	// Process each matched package
	var result []*Package

	// Only analyze non-deps packages (matched ones)
	analyzePkgs := matchedPkgs
	if len(analyzePkgs) == 0 {
		// Fallback: analyze non-standard packages at the end of ordered list
		seen := make(map[string]bool)
		for _, p := range orderedPaths {
			pkg := allPkgs[p]
			if !pkg.Standard && !pkg.Incomplete {
				if !seen[p] {
					seen[p] = true
					analyzePkgs = append(analyzePkgs, p)
				}
			}
		}
	}

	for _, importPath := range analyzePkgs {
		listPkg := allPkgs[importPath]
		if listPkg == nil {
			continue
		}

		// Skip standard library packages
		if listPkg.Standard {
			continue
		}

		goFiles := listPkg.GoFiles
		if includeTests {
			goFiles = append(goFiles, listPkg.TestGoFiles...)
		}

		if len(goFiles) == 0 {
			continue
		}

		pkg, err := loadPackage(listPkg, goFiles, exportMap)
		if err != nil {
			result = append(result, &Package{
				importPath: importPath,
				hasErrors:  true,
				errors:     []string{fmt.Sprintf("%s: %v", importPath, err)},
			})
			continue
		}
		result = append(result, pkg)
	}

	return result, nil
}

func loadPackage(listPkg *GoListPackage, goFiles []string, exportMap map[string]string) (*Package, error) {
	fset := token.NewFileSet()
	var files []*ast.File
	var parseErrors []string
	var hasErrors bool

	// Create a lookup function using export map
	lookup := func(path string) (io.ReadCloser, error) {
		if exportFile, ok := exportMap[path]; ok {
			return os.Open(exportFile)
		}
		return nil, fmt.Errorf("no export data for %s", path)
	}

	cfg := &types.Config{
		Importer: importer.ForCompiler(fset, "gc", lookup),
		Error: func(err error) {
			parseErrors = append(parseErrors, err.Error())
			hasErrors = true
		},
	}

	for _, f := range goFiles {
		var filePath string
		if filepath.IsAbs(f) {
			filePath = f
		} else {
			filePath = filepath.Join(listPkg.Dir, f)
		}

		astFile, err := parser.ParseFile(fset, filePath, nil, 0)
		if err != nil {
			parseErrors = append(parseErrors, fmt.Sprintf("%s: %v", filePath, err))
			hasErrors = true
			if astFile != nil {
				files = append(files, astFile)
			}
			continue
		}
		files = append(files, astFile)
	}

	if hasErrors {
		return &Package{
			importPath: listPkg.ImportPath,
			hasErrors:  true,
			errors:     parseErrors,
		}, nil
	}

	info := &types.Info{
		Types: make(map[ast.Expr]types.TypeAndValue),
		Defs:  make(map[*ast.Ident]types.Object),
		Uses:  make(map[*ast.Ident]types.Object),
	}

	pkg, err := cfg.Check(listPkg.ImportPath, fset, files, info)
	if hasErrors || err != nil {
		errs := parseErrors
		if err != nil && !hasErrors {
			errs = []string{err.Error()}
		}
		return &Package{
			importPath: listPkg.ImportPath,
			hasErrors:  true,
			errors:     errs,
		}, nil
	}

	return &Package{
		importPath: listPkg.ImportPath,
		fset:       fset,
		files:      files,
		typesInfo:  info,
		pkg:        pkg,
	}, nil
}

// JSON output types
type JSONTree map[string]map[string]interface{}

type JSONDiagnostic struct {
	Posn    string `json:"posn"`
	Message string `json:"message"`
}

// printAnalyzerFlags prints the analyzer flags in JSON format.
func printAnalyzerFlags() {
	type flagInfo struct {
		Name  string `json:"Name"`
		Bool  bool   `json:"Bool"`
		Usage string `json:"Usage"`
	}

	flags := []flagInfo{
		{Name: "V", Bool: true, Usage: "print version and exit"},
		{Name: "all", Bool: true, Usage: "no effect (deprecated)"},
		{Name: "c", Bool: false, Usage: "display offending line with this many lines of context"},
		{Name: "diff", Bool: true, Usage: "with -fix, don't update the files, but print a unified diff"},
		{Name: "flags", Bool: true, Usage: "print analyzer flags in JSON"},
		{Name: "json", Bool: true, Usage: "emit JSON output"},
		{Name: "source", Bool: true, Usage: "no effect (deprecated)"},
		{Name: "tags", Bool: false, Usage: "no effect (deprecated)"},
		{Name: "test", Bool: true, Usage: "indicates whether test files should be analyzed, too"},
		{Name: "v", Bool: true, Usage: "no effect (deprecated)"},
	}

	data, _ := json.MarshalIndent(flags, "", "\t")
	fmt.Printf("%s", data)
}

// versionFlag implements the -V flag.
type versionFlag struct{}

func (versionFlag) IsBoolFlag() bool { return true }
func (versionFlag) Get() interface{} { return nil }
func (versionFlag) String() string   { return "" }
func (versionFlag) Set(s string) error {
	if s != "full" {
		log.Fatalf("unsupported flag value: -V=%s (use -V=full)", s)
	}

	progname, err := os.Executable()
	if err != nil {
		return err
	}
	f, err := os.Open(progname)
	if err != nil {
		log.Fatal(err)
	}
	defer f.Close()

	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		log.Fatal(err)
	}

	fmt.Printf("%s version devel comments-go-here buildID=%02x\n",
		filepath.Base(progname), string(h.Sum(nil)))
	os.Exit(0)
	return nil
}
