cat > /workspace/wrapcheck/wrapcheck.go << 'GOEOF'
package wrapcheck

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"path"
	"regexp"
	"strings"
)

// Diagnostic represents a wrapcheck finding.
type Diagnostic struct {
	Pos     token.Position
	Message string
}

// Analyzer runs the wrapcheck analysis on a package.
type Analyzer struct {
	Config      *WrapcheckConfig
	PkgPath     string
	Fset        *token.FileSet
	Files       []*ast.File
	TypesInfo   *types.Info
	Pkg         *types.Package
	Diagnostics []Diagnostic
}

// analysisContext holds context for a single analysis run.
type analysisContext struct {
	cfg         *WrapcheckConfig
	pkgPath     string
	fset        *token.FileSet
	info        *types.Info
	sigRegexps  []*regexp.Regexp
	ifaceRegexps []*regexp.Regexp
	ignoreSigs  []string
}

// Run executes the wrapcheck analysis.
func (a *Analyzer) Run() {
	cfg := a.Config
	if cfg == nil {
		cfg = &WrapcheckConfig{}
	}

	ctx := &analysisContext{
		cfg:        cfg,
		pkgPath:    a.PkgPath,
		fset:       a.Fset,
		info:       a.TypesInfo,
		ignoreSigs: cfg.GetIgnoreSigs(),
	}

	// Compile ignore signature regexps
	for _, pattern := range cfg.IgnoreSigRegexps {
		re, err := regexp.Compile(pattern)
		if err == nil {
			ctx.sigRegexps = append(ctx.sigRegexps, re)
		}
	}

	// Compile interface regexps
	for _, pattern := range cfg.IgnoreInterfaceRegexps {
		re, err := regexp.Compile(pattern)
		if err == nil {
			ctx.ifaceRegexps = append(ctx.ifaceRegexps, re)
		}
	}

	// Walk all files and find function declarations
	for _, file := range a.Files {
		for _, decl := range file.Decls {
			funcDecl, ok := decl.(*ast.FuncDecl)
			if !ok || funcDecl.Body == nil {
				continue
			}
			diags := ctx.analyzeFunc(funcDecl)
			a.Diagnostics = append(a.Diagnostics, diags...)
		}
	}
}

// analyzeFunc analyzes a single function declaration.
func (ctx *analysisContext) analyzeFunc(funcDecl *ast.FuncDecl) []Diagnostic {
	var diags []Diagnostic

	ast.Inspect(funcDecl.Body, func(n ast.Node) bool {
		ret, ok := n.(*ast.ReturnStmt)
		if !ok {
			return true
		}

		for _, result := range ret.Results {
			d := ctx.checkReturnExpr(result, funcDecl.Body)
			if d != nil {
				diags = append(diags, *d)
			}
		}

		return true
	})

	return diags
}

// checkReturnExpr checks a single return expression.
func (ctx *analysisContext) checkReturnExpr(expr ast.Expr, funcBody *ast.BlockStmt) *Diagnostic {
	switch e := expr.(type) {
	case *ast.CallExpr:
		return ctx.checkCallExpr(e)
	case *ast.Ident:
		return ctx.checkIdentReturn(e, funcBody)
	}
	return nil
}

// checkCallExpr checks a direct call expression return.
func (ctx *analysisContext) checkCallExpr(callExpr *ast.CallExpr) *Diagnostic {
	// Must return an error type
	if !ctx.callReturnsError(callExpr) {
		return nil
	}

	return ctx.analyzeCallExpr(callExpr)
}

// callReturnsError checks if a call expression returns an error.
func (ctx *analysisContext) callReturnsError(callExpr *ast.CallExpr) bool {
	tv, ok := ctx.info.Types[callExpr]
	if !ok {
		return false
	}

	if isErrorType(tv.Type) {
		return true
	}

	// Check if it's a tuple with error as the ONLY return?
	// For direct `return someFunc()`, the return expression IS the call
	// and its type is the full tuple. We need to check if error is IN the tuple.
	// But actually wrapcheck only cares when the function returns error directly.
	// If function returns (int, error) and we do `return someFunc()`, 
	// only if the caller also returns (int, error) would this work.
	// The wrapcheck checks if the RETURN TYPE of the function contains error.

	// For simplicity, check if any element of tuple is error
	if tuple, ok := tv.Type.(*types.Tuple); ok {
		for i := 0; i < tuple.Len(); i++ {
			if isErrorType(tuple.At(i).Type()) {
				return true
			}
		}
	}

	return false
}

// analyzeCallExpr performs the wrapcheck analysis on a call expression.
func (ctx *analysisContext) analyzeCallExpr(callExpr *ast.CallExpr) *Diagnostic {
	// Get the callee object
	calleeObj := ctx.getCalleeObject(callExpr)
	if calleeObj == nil {
		return nil
	}

	// Get the function signature string for checking
	funcSig := ctx.getFuncSignature(calleeObj, callExpr)

	// Check ignoreSigs (substring match)
	for _, ignore := range ctx.ignoreSigs {
		if strings.Contains(funcSig, ignore) {
			return nil
		}
	}

	// Check ignoreSigRegexps
	for _, re := range ctx.sigRegexps {
		if re.MatchString(funcSig) {
			return nil
		}
	}

	// Get the package of the callee
	calleePkg := calleeObj.Pkg()

	// Check ignorePackageGlobs
	if calleePkg != nil {
		pkgPath := calleePkg.Path()
		for _, glob := range ctx.cfg.IgnorePackageGlobs {
			matched, err := path.Match(glob, pkgPath)
			if err == nil && matched {
				return nil
			}
		}
	}

	// Check if this is an interface method call
	ifaceType, ifaceTypeName := ctx.getInterfaceType(callExpr)

	if ifaceType != nil {
		// It's an interface call
		if len(ctx.ifaceRegexps) > 0 {
			for _, re := range ctx.ifaceRegexps {
				if re.MatchString(ifaceTypeName) {
					// Matched - for local interfaces suppress, for external fall through
					if calleePkg != nil && calleePkg.Path() == ctx.pkgPath {
						return nil // Suppress local interface error
					}
					// For external interfaces, fall through to external check
					goto checkExternal
				}
			}
			// No regexp matched -> report interface error
			return ctx.makeInterfaceDiag(callExpr, funcSig)
		}
		// No ignoreInterfaceRegexps -> report interface error
		return ctx.makeInterfaceDiag(callExpr, funcSig)
	}

checkExternal:
	if calleePkg == nil {
		return nil
	}

	pkgPath := calleePkg.Path()
	if pkgPath == ctx.pkgPath {
		// Same package
		if ctx.cfg.ReportInternalErrors {
			pos := ctx.fset.Position(callExpr.Pos())
			return &Diagnostic{
				Pos:     pos,
				Message: fmt.Sprintf("package-internal error should be wrapped: sig: %s", funcSig),
			}
		}
		return nil
	}

	// External package
	pos := ctx.fset.Position(callExpr.Pos())
	return &Diagnostic{
		Pos:     pos,
		Message: fmt.Sprintf("error returned from external package is unwrapped: sig: %s", funcSig),
	}
}

func (ctx *analysisContext) makeInterfaceDiag(callExpr *ast.CallExpr, funcSig string) *Diagnostic {
	pos := ctx.fset.Position(callExpr.Pos())
	return &Diagnostic{
