// Diagnostic represents a wrapcheck finding.
type Diagnostic struct {
	Pos     token.Position
	Message string
}

// Analyzer runs the wrapcheck analysis on a package.
type Analyzer struct {
	Config      *WrapcheckConfig
	PkgPath     string
	Fset        *token.FileSet
	Files       []*ast.File
	TypesInfo   *types.Info
	Pkg         *types.Package
	Diagnostics []Diagnostic
