// analysisContext holds context for a single analysis run.
type analysisContext struct {
	cfg         *WrapcheckConfig
	pkgPath     string
	fset        *token.FileSet
	info        *types.Info
	sigRegexps  []*regexp.Regexp
	ifaceRegexps []*regexp.Regexp
	ignoreSigs  []string
}

// Run executes the wrapcheck analysis.
func (a *Analyzer) Run() {
	cfg := a.Config
	if cfg == nil {
		cfg = &WrapcheckConfig{}
	}

	ctx := &analysisContext{
		cfg:        cfg,
		pkgPath:    a.PkgPath,
		fset:       a.Fset,
		info:       a.TypesInfo,
		ignoreSigs: cfg.GetIgnoreSigs(),
	}

