			}
		}

		return true
	})

	return diags
}

// checkReturnExpr checks a single return expression.
func (ctx *analysisContext) checkReturnExpr(expr ast.Expr, funcBody *ast.BlockStmt) *Diagnostic {
	switch e := expr.(type) {
	case *ast.CallExpr:
