// checkCallExpr checks a direct call expression return.
func (ctx *analysisContext) checkCallExpr(callExpr *ast.CallExpr) *Diagnostic {
	// Must return an error type
	if !ctx.callReturnsError(callExpr) {
		return nil
	}

	return ctx.analyzeCallExpr(callExpr)
}

// callReturnsError checks if a call expression returns an error.
func (ctx *analysisContext) callReturnsError(callExpr *ast.CallExpr) bool {
