func (ctx *analysisContext) makeInterfaceDiag(callExpr *ast.CallExpr, funcSig string) *Diagnostic {
	pos := ctx.fset.Position(callExpr.Pos())
	return &Diagnostic{
		Pos:     pos,
		Message: fmt.Sprintf("error returned from interface method should be wrapped: sig: %s", funcSig),
	}
