// checkIdentReturn checks a `return identVar` return statement.
// It finds all assignments to identVar in funcBody and checks if they come from external.
func (ctx *analysisContext) checkIdentReturn(ident *ast.Ident, funcBody *ast.BlockStmt) *Diagnostic {
	// Get the object this ident refers to
	obj, ok := ctx.info.Uses[ident]
	if !ok {
		return nil
	}

	// Must be a variable
	varObj, ok := obj.(*types.Var)
	if !ok {
		return nil
	}

	// Check if the variable's type is error
	if !isErrorType(varObj.Type()) {
		return nil
	}

	// Find all assignments to this variable in the function body
	assignments := ctx.findAssignments(varObj, funcBody)

	if len(assignments) == 0 {
		return nil
	}

	// Check each assignment
	var lastExternalCall *ast.CallExpr
	var lastExternalSig string
	hasUnsafeSource := false

	for _, assign := range assignments {
		call := assign.call
		if call == nil {
			// Non-call assignment (nil, literal, etc.)
			// This is a "safe" source
			continue
		}

		// Analyze this call
		d := ctx.analyzeCallExpr(call)
		if d == nil {
			// This source is safe (suppressed or same pkg)
			hasUnsafeSource = false
			// Reset - if we have a safe source, it overrides
			// Actually, any safe source means we shouldn't flag
			// But we need to track if there's a FINAL safe source
			// For now, mark as safe found
			lastExternalCall = nil
			lastExternalSig = ""
			continue
		}

		// This is an unsafe external source
		hasUnsafeSource = true
		lastExternalCall = call
		lastExternalSig = d.Message
		// Extract just the sig from the message
		if idx := strings.Index(d.Message, "sig: "); idx >= 0 {
			lastExternalSig = d.Message[idx+5:]
		}
	}

	_ = hasUnsafeSource

	if lastExternalCall == nil {
		return nil
	}

	// Use the position of the returned identifier, not the call expression
	pos := ctx.fset.Position(ident.Pos())
	return &Diagnostic{
		Pos:     pos,
		Message: fmt.Sprintf("error returned from external package is unwrapped: sig: %s", lastExternalSig),
	}
}

// assignment represents an assignment to a variable.
type assignment struct {
	call *ast.CallExpr // the call expression assigned, or nil for non-call assignments
	pos  token.Pos    // position of the assignment
}

// findAssignments finds all assignments to a variable within a function body.
func (ctx *analysisContext) findAssignments(varObj *types.Var, body *ast.BlockStmt) []assignment {
	var assignments []assignment
	seen := make(map[token.Pos]bool)

	ast.Inspect(body, func(n ast.Node) bool {
		switch stmt := n.(type) {
		case *ast.AssignStmt:
			// Look for assignments where one of the LHS is our variable
			for i, lhs := range stmt.Lhs {
				lhsIdent, ok := lhs.(*ast.Ident)
				if !ok {
					continue
				}
				lhsObj, ok := ctx.info.Defs[lhsIdent]
				if !ok {
					lhsObj, ok = ctx.info.Uses[lhsIdent]
					if !ok {
						continue
					}
				}

				if lhsObj != varObj {
					continue
				}

				if seen[stmt.Pos()] {
					continue
				}
				seen[stmt.Pos()] = true

				// Find the corresponding RHS
				var rhs ast.Expr
				if len(stmt.Rhs) == 1 {
					// Either direct assignment or multi-return
					rhs = stmt.Rhs[0]
				} else if i < len(stmt.Rhs) {
					// Multiple RHS expressions (x, y = a, b)
					rhs = stmt.Rhs[i]
				}

				if rhs == nil {
					continue
				}

				callExpr, ok := rhs.(*ast.CallExpr)
				if ok {
					assignments = append(assignments, assignment{call: callExpr, pos: stmt.Pos()})
				} else {
					// Non-call RHS (literal, nil, etc.) - still a safe assignment
					assignments = append(assignments, assignment{call: nil, pos: stmt.Pos()})
				}
			}

		case *ast.ValueSpec:
			// var x = someFunc() or x := someFunc()
			for i, name := range stmt.Names {
				nameObj, ok := ctx.info.Defs[name]
				if !ok {
					continue
				}
				if nameObj != varObj {
					continue
				}
				if seen[stmt.Pos()] {
					continue
				}
				seen[stmt.Pos()] = true

				if len(stmt.Values) == 0 {
					// var x error (zero value)
					assignments = append(assignments, assignment{call: nil, pos: stmt.Pos()})
					continue
				}

				var rhs ast.Expr
				if len(stmt.Values) == 1 {
					rhs = stmt.Values[0]
				} else if i < len(stmt.Values) {
					rhs = stmt.Values[i]
				}

				if rhs == nil {
					continue
				}

				callExpr, ok := rhs.(*ast.CallExpr)
				if ok {
					assignments = append(assignments, assignment{call: callExpr, pos: stmt.Pos()})
				} else {
					assignments = append(assignments, assignment{call: nil, pos: stmt.Pos()})
				}
			}
		}

		return true
	})

	return assignments
}

// getCalleeObject returns the types.Object for the callee of a CallExpr.
func (ctx *analysisContext) getCalleeObject(callExpr *ast.CallExpr) types.Object {
	switch fn := callExpr.Fun.(type) {
	case *ast.SelectorExpr:
		if obj, ok := ctx.info.Uses[fn.Sel]; ok {
			return obj
		}
	case *ast.Ident:
		if obj, ok := ctx.info.Uses[fn]; ok {
			return obj
		}
	}
	return nil
}

// isErrorType checks if t is the error interface.
func isErrorType(t types.Type) bool {
	return t != nil && t.String() == "error"
}

// getInterfaceType returns the interface type if the call is a method call on an interface.
func (ctx *analysisContext) getInterfaceType(callExpr *ast.CallExpr) (types.Type, string) {
	sel, ok := callExpr.Fun.(*ast.SelectorExpr)
	if !ok {
		return nil, ""
	}

	recvTV, ok := ctx.info.Types[sel.X]
	if !ok {
		return nil, ""
	}

	recvType := recvTV.Type
	if ptr, ok := recvType.(*types.Pointer); ok {
		recvType = ptr.Elem()
	}

	named, ok := recvType.(*types.Named)
	if !ok {
		if iface, ok := recvType.(*types.Interface); ok {
			return iface, ""
		}
		return nil, ""
	}

	underlying := named.Underlying()
	if _, ok := underlying.(*types.Interface); ok {
		typeName := named.String()
		return underlying, typeName
	}

	return nil, ""
}

// getFuncSignature returns the function signature string.
func (ctx *analysisContext) getFuncSignature(obj types.Object, callExpr *ast.CallExpr) string {
	// Check if this is a method call on an interface type
	sel, isSel := callExpr.Fun.(*ast.SelectorExpr)
	if isSel {
		recvTV, ok := ctx.info.Types[sel.X]
		if ok {
			recvType := recvTV.Type
			if ptr, ok := recvType.(*types.Pointer); ok {
				recvType = ptr.Elem()
			}
			if named, ok := recvType.(*types.Named); ok {
				if _, ok := named.Underlying().(*types.Interface); ok {
					fn, ok := obj.(*types.Func)
					if ok {
						sig := fn.Type().(*types.Signature)
						typeName := named.String()
						return formatInterfaceSig(typeName, fn.Name(), sig)
					}
				}
			}
		}
	}

	fn, ok := obj.(*types.Func)
	if !ok {
		return obj.String()
	}

	return formatFuncSig(fn)
}

// formatFuncSig formats a function signature.
func formatFuncSig(fn *types.Func) string {
	sig := fn.Type().(*types.Signature)
	recv := sig.Recv()

	var sb strings.Builder
	sb.WriteString("func ")

	if recv != nil {
		recvType := recv.Type()
		sb.WriteString("(")
		sb.WriteString(recvType.String())
		sb.WriteString(")")
		sb.WriteString(".")
		sb.WriteString(fn.Name())
	} else {
		pkg := fn.Pkg()
		if pkg != nil {
			sb.WriteString(pkg.Path())
			sb.WriteString(".")
		}
		sb.WriteString(fn.Name())
	}

	sb.WriteString(formatParams(sig))
	result := formatResults(sig)
	if result != "" {
		sb.WriteString(" ")
		sb.WriteString(result)
	}

	return sb.String()
}

// formatInterfaceSig formats a method signature for an interface type.
func formatInterfaceSig(typeName, methodName string, sig *types.Signature) string {
	var sb strings.Builder
	sb.WriteString("func (")
	sb.WriteString(typeName)
	sb.WriteString(").")
	sb.WriteString(methodName)
	sb.WriteString(formatParams(sig))
	result := formatResults(sig)
	if result != "" {
		sb.WriteString(" ")
		sb.WriteString(result)
	}
	return sb.String()
}

// formatParams formats function parameters.
func formatParams(sig *types.Signature) string {
	params := sig.Params()
	if params.Len() == 0 {
		return "()"
	}

	var parts []string
	for i := 0; i < params.Len(); i++ {
		p := params.At(i)
		name := p.Name()

		if sig.Variadic() && i == params.Len()-1 {
			sliceType, ok := p.Type().(*types.Slice)
			if ok {
				elemStr := types.TypeString(sliceType.Elem(), nil)
				if name != "" {
					parts = append(parts, name+" ..."+elemStr)
				} else {
					parts = append(parts, "..."+elemStr)
				}
				continue
			}
		}

		typeStr := types.TypeString(p.Type(), nil)
		if name != "" {
			parts = append(parts, name+" "+typeStr)
		} else {
			parts = append(parts, typeStr)
		}
	}

	return "(" + strings.Join(parts, ", ") + ")"
}

// formatResults formats function return types.
func formatResults(sig *types.Signature) string {
	results := sig.Results()
	if results.Len() == 0 {
		return ""
	}

	if results.Len() == 1 {
		r := results.At(0)
		name := r.Name()
		typeStr := types.TypeString(r.Type(), nil)
		if name != "" {
			return name + " " + typeStr
		}
		return typeStr
	}

	var parts []string
	for i := 0; i < results.Len(); i++ {
		r := results.At(i)
		name := r.Name()
		typeStr := types.TypeString(r.Type(), nil)
		if name != "" {
			parts = append(parts, name+" "+typeStr)
		} else {
			parts = append(parts, typeStr)
		}
	}
	return "(" + strings.Join(parts, ", ") + ")"
}
