package wrapcheck

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"path"
	"regexp"
	"strings"
)

// Diagnostic represents a wrapcheck finding.
type Diagnostic struct {
	Pos     token.Position
	Message string
}

// Analyzer runs the wrapcheck analysis on a package.
type Analyzer struct {
	Config      *WrapcheckConfig
	PkgPath     string
	Fset        *token.FileSet
	Files       []*ast.File
	TypesInfo   *types.Info
	Pkg         *types.Package
	Diagnostics []Diagnostic
}

// analysisContext holds context for a single analysis run.
type analysisContext struct {
	cfg         *WrapcheckConfig
	pkgPath     string
	fset        *token.FileSet
	info        *types.Info
	sigRegexps  []*regexp.Regexp
	ifaceRegexps []*regexp.Regexp
	ignoreSigs  []string
}

// Run executes the wrapcheck analysis.
func (a *Analyzer) Run() {
	cfg := a.Config
	if cfg == nil {
		cfg = &WrapcheckConfig{}
	}

	ctx := &analysisContext{
		cfg:        cfg,
		pkgPath:    a.PkgPath,
		fset:       a.Fset,
		info:       a.TypesInfo,
		ignoreSigs: cfg.GetIgnoreSigs(),
	}

	// Compile ignore signature regexps
	for _, pattern := range cfg.IgnoreSigRegexps {
		re, err := regexp.Compile(pattern)
		if err == nil {
			ctx.sigRegexps = append(ctx.sigRegexps, re)
		}
	}

	// Compile interface regexps
	for _, pattern := range cfg.IgnoreInterfaceRegexps {
		re, err := regexp.Compile(pattern)
		if err == nil {
			ctx.ifaceRegexps = append(ctx.ifaceRegexps, re)
		}
	}

	// Walk all files and find function declarations
	for _, file := range a.Files {
		for _, decl := range file.Decls {
			funcDecl, ok := decl.(*ast.FuncDecl)
			if !ok || funcDecl.Body == nil {
				continue
			}
			diags := ctx.analyzeFunc(funcDecl)
			a.Diagnostics = append(a.Diagnostics, diags...)
		}
	}
}

// analyzeFunc analyzes a single function declaration.
func (ctx *analysisContext) analyzeFunc(funcDecl *ast.FuncDecl) []Diagnostic {
	var diags []Diagnostic

	ast.Inspect(funcDecl.Body, func(n ast.Node) bool {
		ret, ok := n.(*ast.ReturnStmt)
		if !ok {
			return true
		}

		for _, result := range ret.Results {
			d := ctx.checkReturnExpr(result, funcDecl.Body)
			if d != nil {
				diags = append(diags, *d)
			}
		}

		return true
	})

	return diags
}

// checkReturnExpr checks a single return expression.
func (ctx *analysisContext) checkReturnExpr(expr ast.Expr, funcBody *ast.BlockStmt) *Diagnostic {
	switch e := expr.(type) {
	case *ast.CallExpr:
		return ctx.checkCallExpr(e)
	case *ast.Ident:
		return ctx.checkIdentReturn(e, funcBody)
	}
	return nil
}

// checkCallExpr checks a direct call expression return.
func (ctx *analysisContext) checkCallExpr(callExpr *ast.CallExpr) *Diagnostic {
	// Must return an error type
	if !ctx.callReturnsError(callExpr) {
		return nil
	}

	return ctx.analyzeCallExpr(callExpr)
}

// callReturnsError checks if a call expression returns an error.
func (ctx *analysisContext) callReturnsError(callExpr *ast.CallExpr) bool {
	tv, ok := ctx.info.Types[callExpr]
	if !ok {
		return false
	}

	if isErrorType(tv.Type) {
		return true
	}

	// Check if it's a tuple with error as the ONLY return?
	// For direct `return someFunc()`, the return expression IS the call
	// and its type is the full tuple. We need to check if error is IN the tuple.
	// But actually wrapcheck only cares when the function returns error directly.
	// If function returns (int, error) and we do `return someFunc()`, 
	// only if the caller also returns (int, error) would this work.
	// The wrapcheck checks if the RETURN TYPE of the function contains error.

	// For simplicity, check if any element of tuple is error
	if tuple, ok := tv.Type.(*types.Tuple); ok {
		for i := 0; i < tuple.Len(); i++ {
			if isErrorType(tuple.At(i).Type()) {
				return true
			}
		}
	}

	return false
}

// analyzeCallExpr performs the wrapcheck analysis on a call expression.
func (ctx *analysisContext) analyzeCallExpr(callExpr *ast.CallExpr) *Diagnostic {
	// Get the callee object
	calleeObj := ctx.getCalleeObject(callExpr)
	if calleeObj == nil {
		return nil
	}

	// Get the function signature string for checking
	funcSig := ctx.getFuncSignature(calleeObj, callExpr)

	// Check ignoreSigs (substring match)
	for _, ignore := range ctx.ignoreSigs {
		if strings.Contains(funcSig, ignore) {
			return nil
		}
	}

	// Check ignoreSigRegexps
	for _, re := range ctx.sigRegexps {
		if re.MatchString(funcSig) {
			return nil
		}
	}

	// Get the package of the callee
	calleePkg := calleeObj.Pkg()

	// Check ignorePackageGlobs
	if calleePkg != nil {
		pkgPath := calleePkg.Path()
		for _, glob := range ctx.cfg.IgnorePackageGlobs {
			matched, err := path.Match(glob, pkgPath)
			if err == nil && matched {
				return nil
			}
		}
	}

	// Check if this is an interface method call
	ifaceType, ifaceTypeName := ctx.getInterfaceType(callExpr)

	if ifaceType != nil {
		// It's an interface call
		if len(ctx.ifaceRegexps) > 0 {
			for _, re := range ctx.ifaceRegexps {
				if re.MatchString(ifaceTypeName) {
					// Matched - for local interfaces suppress, for external fall through
					if calleePkg != nil && calleePkg.Path() == ctx.pkgPath {
						return nil // Suppress local interface error
					}
					// For external interfaces, fall through to external check
					goto checkExternal
				}
			}
			// No regexp matched -> report interface error
			return ctx.makeInterfaceDiag(callExpr, funcSig)
		}
		// No ignoreInterfaceRegexps -> report interface error
		return ctx.makeInterfaceDiag(callExpr, funcSig)
	}

checkExternal:
	if calleePkg == nil {
		return nil
	}

	pkgPath := calleePkg.Path()
	if pkgPath == ctx.pkgPath {
		// Same package
		if ctx.cfg.ReportInternalErrors {
			pos := ctx.fset.Position(callExpr.Pos())
			return &Diagnostic{
				Pos:     pos,
				Message: fmt.Sprintf("package-internal error should be wrapped: sig: %s", funcSig),
			}
		}
		return nil
	}

	// External package
	pos := ctx.fset.Position(callExpr.Pos())
	return &Diagnostic{
		Pos:     pos,
		Message: fmt.Sprintf("error returned from external package is unwrapped: sig: %s", funcSig),
	}
}

func (ctx *analysisContext) makeInterfaceDiag(callExpr *ast.CallExpr, funcSig string) *Diagnostic {
	pos := ctx.fset.Position(callExpr.Pos())
	return &Diagnostic{
		Pos:     pos,
		Message: fmt.Sprintf("error returned from interface method should be wrapped: sig: %s", funcSig),
	}
}

// checkIdentReturn checks a `return identVar` return statement.
// It finds all assignments to identVar in funcBody and checks if they come from external.
func (ctx *analysisContext) checkIdentReturn(ident *ast.Ident, funcBody *ast.BlockStmt) *Diagnostic {
	// Get the object this ident refers to
	obj, ok := ctx.info.Uses[ident]
	if !ok {
		return nil
	}

	// Must be a variable
	varObj, ok := obj.(*types.Var)
	if !ok {
		return nil
	}

	// Check if the variable's type is error
	if !isErrorType(varObj.Type()) {
		return nil
	}

	// Find all assignments to this variable in the function body
	assignments := ctx.findAssignments(varObj, funcBody)

	if len(assignments) == 0 {
		return nil
	}

	// Check each assignment
	var lastExternalCall *ast.CallExpr
	var lastExternalSig string
	hasUnsafeSource := false

	for _, assign := range assignments {
		call := assign.call
		if call == nil {
			// Non-call assignment (nil, literal, etc.)
			// This is a "safe" source
			continue
		}

		// Analyze this call
		d := ctx.analyzeCallExpr(call)
		if d == nil {
			// This source is safe (suppressed or same pkg)
			hasUnsafeSource = false
			// Reset - if we have a safe source, it overrides
			// Actually, any safe source means we shouldn't flag
			// But we need to track if there's a FINAL safe source
			// For now, mark as safe found
			lastExternalCall = nil
			lastExternalSig = ""
			continue
		}

		// This is an unsafe external source
		hasUnsafeSource = true
		lastExternalCall = call
		lastExternalSig = d.Message
		// Extract just the sig from the message
		if idx := strings.Index(d.Message, "sig: "); idx >= 0 {
			lastExternalSig = d.Message[idx+5:]
		}
	}

	_ = hasUnsafeSource

	if lastExternalCall == nil {
		return nil
	}

	// Use the position of the returned identifier, not the call expression
	pos := ctx.fset.Position(ident.Pos())
	return &Diagnostic{
		Pos:     pos,
		Message: fmt.Sprintf("error returned from external package is unwrapped: sig: %s", lastExternalSig),
	}
}

// assignment represents an assignment to a variable.
type assignment struct {
	call *ast.CallExpr // the call expression assigned, or nil for non-call assignments
	pos  token.Pos    // position of the assignment
}

// findAssignments finds all assignments to a variable within a function body.
func (ctx *analysisContext) findAssignments(varObj *types.Var, body *ast.BlockStmt) []assignment {
	var assignments []assignment
	seen := make(map[token.Pos]bool)

	ast.Inspect(body, func(n ast.Node) bool {
		switch stmt := n.(type) {
		case *ast.AssignStmt:
			// Look for assignments where one of the LHS is our variable
			for i, lhs := range stmt.Lhs {
				lhsIdent, ok := lhs.(*ast.Ident)
				if !ok {
					continue
				}
				lhsObj, ok := ctx.info.Defs[lhsIdent]
				if !ok {
					lhsObj, ok = ctx.info.Uses[lhsIdent]
					if !ok {
						continue
					}
				}

				if lhsObj != varObj {
					continue
				}

				if seen[stmt.Pos()] {
					continue
				}
				seen[stmt.Pos()] = true

				// Find the corresponding RHS
				var rhs ast.Expr
				if len(stmt.Rhs) == 1 {
					// Either direct assignment or multi-return
					rhs = stmt.Rhs[0]
				} else if i < len(stmt.Rhs) {
					// Multiple RHS expressions (x, y = a, b)
					rhs = stmt.Rhs[i]
				}

				if rhs == nil {
					continue
				}

				callExpr, ok := rhs.(*ast.CallExpr)
				if ok {
					assignments = append(assignments, assignment{call: callExpr, pos: stmt.Pos()})
				} else {
					// Non-call RHS (literal, nil, etc.) - still a safe assignment
					assignments = append(assignments, assignment{call: nil, pos: stmt.Pos()})
				}
			}

		case *ast.ValueSpec:
			// var x = someFunc() or x := someFunc()
			for i, name := range stmt.Names {
				nameObj, ok := ctx.info.Defs[name]
				if !ok {
					continue
				}
				if nameObj != varObj {
					continue
				}
				if seen[stmt.Pos()] {
					continue
				}
				seen[stmt.Pos()] = true

				if len(stmt.Values) == 0 {
					// var x error (zero value)
					assignments = append(assignments, assignment{call: nil, pos: stmt.Pos()})
					continue
				}

				var rhs ast.Expr
				if len(stmt.Values) == 1 {
					rhs = stmt.Values[0]
				} else if i < len(stmt.Values) {
					rhs = stmt.Values[i]
				}

				if rhs == nil {
					continue
				}

				callExpr, ok := rhs.(*ast.CallExpr)
				if ok {
					assignments = append(assignments, assignment{call: callExpr, pos: stmt.Pos()})
				} else {
					assignments = append(assignments, assignment{call: nil, pos: stmt.Pos()})
				}
			}
		}

		return true
	})

	return assignments
}

// getCalleeObject returns the types.Object for the callee of a CallExpr.
func (ctx *analysisContext) getCalleeObject(callExpr *ast.CallExpr) types.Object {
	switch fn := callExpr.Fun.(type) {
	case *ast.SelectorExpr:
		if obj, ok := ctx.info.Uses[fn.Sel]; ok {
			return obj
		}
	case *ast.Ident:
		if obj, ok := ctx.info.Uses[fn]; ok {
			return obj
		}
	}
	return nil
}

// isErrorType checks if t is the error interface.
func isErrorType(t types.Type) bool {
	return t != nil && t.String() == "error"
}

// getInterfaceType returns the interface type if the call is a method call on an interface.
func (ctx *analysisContext) getInterfaceType(callExpr *ast.CallExpr) (types.Type, string) {
	sel, ok := callExpr.Fun.(*ast.SelectorExpr)
	if !ok {
		return nil, ""
	}

	recvTV, ok := ctx.info.Types[sel.X]
	if !ok {
		return nil, ""
	}

	recvType := recvTV.Type
	if ptr, ok := recvType.(*types.Pointer); ok {
		recvType = ptr.Elem()
	}

	named, ok := recvType.(*types.Named)
	if !ok {
		if iface, ok := recvType.(*types.Interface); ok {
			return iface, ""
		}
		return nil, ""
	}

	underlying := named.Underlying()
	if _, ok := underlying.(*types.Interface); ok {
		typeName := named.String()
		return underlying, typeName
	}

	return nil, ""
}

// getFuncSignature returns the function signature string.
func (ctx *analysisContext) getFuncSignature(obj types.Object, callExpr *ast.CallExpr) string {
	// Check if this is a method call on an interface type
	sel, isSel := callExpr.Fun.(*ast.SelectorExpr)
	if isSel {
		recvTV, ok := ctx.info.Types[sel.X]
		if ok {
			recvType := recvTV.Type
			if ptr, ok := recvType.(*types.Pointer); ok {
				recvType = ptr.Elem()
			}
			if named, ok := recvType.(*types.Named); ok {
				if _, ok := named.Underlying().(*types.Interface); ok {
					fn, ok := obj.(*types.Func)
					if ok {
						sig := fn.Type().(*types.Signature)
						typeName := named.String()
						return formatInterfaceSig(typeName, fn.Name(), sig)
					}
				}
			}
		}
	}

	fn, ok := obj.(*types.Func)
	if !ok {
		return obj.String()
	}

	return formatFuncSig(fn)
}

// formatFuncSig formats a function signature.
func formatFuncSig(fn *types.Func) string {
	sig := fn.Type().(*types.Signature)
	recv := sig.Recv()

	var sb strings.Builder
	sb.WriteString("func ")

	if recv != nil {
		recvType := recv.Type()
		sb.WriteString("(")
		sb.WriteString(recvType.String())
		sb.WriteString(")")
		sb.WriteString(".")
		sb.WriteString(fn.Name())
	} else {
		pkg := fn.Pkg()
		if pkg != nil {
			sb.WriteString(pkg.Path())
			sb.WriteString(".")
		}
		sb.WriteString(fn.Name())
	}

	sb.WriteString(formatParams(sig))
	result := formatResults(sig)
	if result != "" {
		sb.WriteString(" ")
		sb.WriteString(result)
	}

	return sb.String()
}

// formatInterfaceSig formats a method signature for an interface type.
func formatInterfaceSig(typeName, methodName string, sig *types.Signature) string {
	var sb strings.Builder
	sb.WriteString("func (")
	sb.WriteString(typeName)
	sb.WriteString(").")
	sb.WriteString(methodName)
	sb.WriteString(formatParams(sig))
	result := formatResults(sig)
	if result != "" {
		sb.WriteString(" ")
		sb.WriteString(result)
	}
	return sb.String()
}

// formatParams formats function parameters.
func formatParams(sig *types.Signature) string {
	params := sig.Params()
	if params.Len() == 0 {
		return "()"
	}

	var parts []string
	for i := 0; i < params.Len(); i++ {
		p := params.At(i)
		name := p.Name()

		if sig.Variadic() && i == params.Len()-1 {
			sliceType, ok := p.Type().(*types.Slice)
			if ok {
				elemStr := types.TypeString(sliceType.Elem(), nil)
				if name != "" {
					parts = append(parts, name+" ..."+elemStr)
				} else {
					parts = append(parts, "..."+elemStr)
				}
				continue
			}
		}

		typeStr := types.TypeString(p.Type(), nil)
		if name != "" {
			parts = append(parts, name+" "+typeStr)
		} else {
			parts = append(parts, typeStr)
		}
	}

	return "(" + strings.Join(parts, ", ") + ")"
}

// formatResults formats function return types.
func formatResults(sig *types.Signature) string {
	results := sig.Results()
	if results.Len() == 0 {
		return ""
	}

	if results.Len() == 1 {
		r := results.At(0)
		name := r.Name()
		typeStr := types.TypeString(r.Type(), nil)
		if name != "" {
			return name + " " + typeStr
		}
		return typeStr
	}

	var parts []string
	for i := 0; i < results.Len(); i++ {
		r := results.At(i)
		name := r.Name()
		typeStr := types.TypeString(r.Type(), nil)
		if name != "" {
			parts = append(parts, name+" "+typeStr)
		} else {
			parts = append(parts, typeStr)
		}
	}
	return "(" + strings.Join(parts, ", ") + ")"
}
GOEOF

