cat > /workspace/wrapcheck/config.go << 'GOEOF'
package wrapcheck

import (
	"bufio"
	"io"
	"os"
	"path/filepath"
	"strings"
)

// WrapcheckConfig contains configuration for the wrapcheck analyzer.
type WrapcheckConfig struct {
	// IgnoreSigs is a list of substrings of signatures to ignore.
	// If set, it overrides the default set.
	IgnoreSigs []string `yaml:"ignoreSigs"`

	// ExtraIgnoreSigs adds to the default set of ignoreSigs.
	ExtraIgnoreSigs []string `yaml:"extraIgnoreSigs"`

	// IgnoreSigRegexps is a list of regexps to match against signatures to ignore.
	IgnoreSigRegexps []string `yaml:"ignoreSigRegexps"`

	// IgnorePackageGlobs is a list of glob patterns. If the package of a
	// function matches any of these, it will be ignored.
	IgnorePackageGlobs []string `yaml:"ignorePackageGlobs"`

	// IgnoreInterfaceRegexps is a list of regexps for interface names to ignore.
	IgnoreInterfaceRegexps []string `yaml:"ignoreInterfaceRegexps"`

	// ReportInternalErrors determines whether to report errors returned from
	// inside the same package.
	ReportInternalErrors bool `yaml:"reportInternalErrors"`
}

// DefaultIgnoreSigs is the default set of function signature substrings to ignore.
var DefaultIgnoreSigs = []string{
	".Errorf(",
	"errors.New(",
	"errors.Unwrap(",
	"errors.Join(",
	".Wrap(",
	".Wrapf(",
	".WithMessage(",
	".WithMessagef(",
	".WithStack(",
}

// LoadConfig loads the wrapcheck configuration from the given directory or home dir.
func LoadConfig(dir string) (*WrapcheckConfig, error) {
	// Try local directory first
	localPath := filepath.Join(dir, ".wrapcheck.yaml")
	if cfg, err := parseConfigFile(localPath); err == nil {
		return cfg, nil
	}

	// Try home directory
	home, err := os.UserHomeDir()
	if err == nil {
		homePath := filepath.Join(home, ".wrapcheck.yaml")
		if cfg, err := parseConfigFile(homePath); err == nil {
			return cfg, nil
		}
	}

	return &WrapcheckConfig{}, nil
}

// parseConfigFile parses a .wrapcheck.yaml file.
func parseConfigFile(path string) (*WrapcheckConfig, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	return parseConfig(f)
}

// parseConfig parses wrapcheck config from a reader.
// This is a simple YAML parser that handles the specific format used.
func parseConfig(r io.Reader) (*WrapcheckConfig, error) {
	cfg := &WrapcheckConfig{}
	scanner := bufio.NewScanner(r)

	var currentKey string

	for scanner.Scan() {
		line := scanner.Text()

		// Skip empty lines and comments
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}

		// Check if this is a list item (starts with "- " possibly with leading whitespace)
		if strings.HasPrefix(trimmed, "- ") {
			if currentKey != "" {
				item := strings.TrimPrefix(trimmed, "- ")
				item = unquoteYAML(item)
				appendListField(cfg, currentKey, item)
			}
			continue
		}

		// Check if this is a list item with just "-" (empty item, rare but possible)
		if trimmed == "-" {
			if currentKey != "" {
				appendListField(cfg, currentKey, "")
			}
			continue
		}

		// It's a key-value pair
		if idx := strings.Index(trimmed, ":"); idx >= 0 {
			key := strings.TrimSpace(trimmed[:idx])
			value := strings.TrimSpace(trimmed[idx+1:])

			currentKey = key

			// Handle inline list like "key: []"
			if value == "[]" {
				setListField(cfg, key, []string{})
				continue
			}

			// Handle boolean
			if value == "true" || value == "false" {
				setBoolField(cfg, key, value == "true")
				// After a boolean, next line is NOT a list item
				currentKey = ""
				continue
			}

			// Handle inline list like "key: [a, b, c]"
			if strings.HasPrefix(value, "[") && strings.HasSuffix(value, "]") {
				inner := value[1 : len(value)-1]
				items := parseInlineList(inner)
				setListField(cfg, key, items)
				currentKey = ""
				continue
			}

			// Handle non-empty scalar value
			if value != "" {
				// Could be a string value
				currentKey = ""
			}
			// If value is empty, currentKey is set and we expect list items next
		}
	}

	return cfg, scanner.Err()
}

func parseInlineList(s string) []string {
	if s == "" {
		return []string{}
	}
	parts := strings.Split(s, ",")
	result := make([]string, 0, len(parts))
	for _, p := range parts {
		p = strings.TrimSpace(p)
		p = unquoteYAML(p)
		if p != "" {
			result = append(result, p)
		}
	}
	return result
}

func unquoteYAML(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= 2 {
		if (s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '\'' && s[len(s)-1] == '\'') {
			return s[1 : len(s)-1]
		}
	}
