		}
	}

	os.Exit(exitCode)
}

// printPackageErrors prints errors for a failed package in the original format.
func printPackageErrors(pkg *Package) {
	if len(pkg.errors) == 0 {
		fmt.Fprintf(os.Stderr, "-: # %s\n", pkg.importPath)
		fmt.Fprintf(os.Stderr, "%s: analysis skipped due to errors in package\n", analyzerName)
		return
	}

	firstError := true
	for _, e := range pkg.errors {
		// Split each error by newlines
		lines := strings.Split(strings.TrimRight(e, "\n"), "\n")
		for _, line := range lines {
			if line == "" {
				continue
			}
			if firstError {
				fmt.Fprintf(os.Stderr, "-: %s\n", line)
				firstError = false
			} else {
				fmt.Fprintf(os.Stderr, "%s\n", line)
			}
		}
	}
	fmt.Fprintf(os.Stderr, "%s: analysis skipped due to errors in package\n", analyzerName)
}

