		allPkgs[pkg.ImportPath] = &pkg
		if len(pkg.Match) > 0 && !pkg.Standard {
			found := false
			for _, m := range matchedPkgs {
				if m == pkg.ImportPath {
					found = true
					break
				}
			}
			if !found {
