cat > /workspace/cmd/wrapcheck/main.go << 'GOEOF'
package main

import (
	"crypto/sha256"
	"encoding/json"
	"flag"
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/token"
	"go/types"
	"io"
	"log"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/tomarrell/wrapcheck/v2/wrapcheck"
)

var (
	jsonOutput = flag.Bool("json", false, "emit JSON output")
	contextN   = flag.Int("c", -1, "display offending line with this many lines of context")
	testFiles  = flag.Bool("test", true, "indicates whether test files should be analyzed, too")
	_          = flag.Bool("all", false, "no effect (deprecated)")
	_          = flag.Bool("source", false, "no effect (deprecated)")
	_          = flag.Bool("v", false, "no effect (deprecated)")
	_          = flag.String("tags", "", "no effect (deprecated)")
	_          = flag.String("cpuprofile", "", "write CPU profile to this file")
	_          = flag.String("memprofile", "", "write memory profile to this file")
	_          = flag.String("debug", "", `debug flags, any subset of "fpstv"`)
	_          = flag.String("trace", "", "write trace log to this file")
	_          = flag.Bool("diff", false, "with -fix, don't update the files, but print a unified diff")
	_          = flag.Bool("fix", false, "apply all suggested fixes")
)

const analyzerName = "wrapcheck"
const analyzerDoc = "Checks that errors returned from external packages are wrapped"

func init() {
	flag.Var(&versionFlag{}, "V", "print version and exit")
	flag.Bool("flags", false, "print analyzer flags in JSON")
}

func main() {
	log.SetFlags(0)
	log.SetPrefix(analyzerName + ": ")

	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, "%s: %s\n\nUsage: %s [-flag] [package]\n\n\nFlags:\n", analyzerName, analyzerDoc, analyzerName)
		flag.PrintDefaults()
	}

	flag.Parse()

	// Handle -flags after parsing
	if f := flag.Lookup("flags"); f != nil && f.Value.String() == "true" {
		printAnalyzerFlags()
		os.Exit(0)
	}

	args := flag.Args()
	if len(args) == 0 {
		flag.Usage()
		os.Exit(1)
	}

	// Load configuration
	cwd, err := os.Getwd()
	if err != nil {
		cwd = "."
	}
	cfg, err := wrapcheck.LoadConfig(cwd)
	if err != nil {
		log.Printf("error loading config: %v", err)
	}

	// Load and analyze packages
	pkgs, err := loadPackages(args, *testFiles)
	if err != nil {
		log.Printf("failed to load packages: %v", err)
		os.Exit(1)
	}

	exitCode := 0
	jsonTree := make(JSONTree)

	// Separate error packages from valid packages (maintain original order within each group)
	var errorPkgs []*Package
	var validPkgs []*Package
	for _, pkg := range pkgs {
		if pkg.hasErrors {
			errorPkgs = append(errorPkgs, pkg)
		} else {
			validPkgs = append(validPkgs, pkg)
		}
	}

	// Phase 1: Print error messages for all error packages
	for _, pkg := range errorPkgs {
		printPackageErrorLines(pkg)
	}

	// Phase 2: Print "analysis skipped" for all error packages
	for range errorPkgs {
		fmt.Fprintf(os.Stderr, "%s: analysis skipped due to errors in package\n", analyzerName)
		exitCode = 1
	}

	// Phase 3: Analyze and print diagnostics for valid packages
	for _, pkg := range validPkgs {
		analyzer := &wrapcheck.Analyzer{
			Config:    cfg,
			PkgPath:   pkg.importPath,
			Fset:      pkg.fset,
			Files:     pkg.files,
			TypesInfo: pkg.typesInfo,
			Pkg:       pkg.pkg,
		}
		analyzer.Run()

		if len(analyzer.Diagnostics) > 0 {
			exitCode = 1
		}

		if *jsonOutput {
			diags := make([]JSONDiagnostic, 0, len(analyzer.Diagnostics))
			for _, d := range analyzer.Diagnostics {
				diags = append(diags, JSONDiagnostic{
					Posn:    d.Pos.String(),
					Message: d.Message,
				})
			}
			if len(diags) > 0 {
				if jsonTree[pkg.importPath] == nil {
					jsonTree[pkg.importPath] = make(map[string]interface{})
				}
				jsonTree[pkg.importPath][analyzerName] = diags
			}
		} else {
			for _, d := range analyzer.Diagnostics {
				fmt.Fprintf(os.Stderr, "%s: %s\n", d.Pos, d.Message)
				if *contextN >= 0 {
					printContext(d.Pos, *contextN)
				}
			}
		}
	}

	if *jsonOutput && len(jsonTree) > 0 {
		data, err := json.MarshalIndent(jsonTree, "", "\t")
		if err != nil {
			log.Printf("json marshal error: %v", err)
		} else {
			fmt.Printf("%s\n", data)
		}
	}

	os.Exit(exitCode)
}

// printPackageErrorLines prints the error lines for a failed package.
func printPackageErrorLines(pkg *Package) {
	if len(pkg.errors) == 0 {
		return
	}

	firstLine := true
	for _, e := range pkg.errors {
		lines := strings.Split(strings.TrimRight(e, "\n"), "\n")
		for _, line := range lines {
			if line == "" {
				continue
			}
			if firstLine {
				fmt.Fprintf(os.Stderr, "-: %s\n", line)
				firstLine = false
			} else {
				fmt.Fprintf(os.Stderr, "%s\n", line)
			}
		}
	}
}

func printContext(pos token.Position, n int) {
	data, err := os.ReadFile(pos.Filename)
	if err != nil {
		return
	}
	lines := strings.Split(string(data), "\n")
	start := pos.Line - n
	end := pos.Line + n
	for i := start; i <= end; i++ {
		if 1 <= i && i <= len(lines) {
			fmt.Fprintf(os.Stderr, "%d\t%s\n", i, lines[i-1])
		}
	}
}

// GoListPackage is the JSON output from go list.
type GoListPackage struct {
	Dir          string
	ImportPath   string
	Name         string
	GoFiles      []string
	TestGoFiles  []string
	XTestGoFiles []string
	CgoFiles     []string
	Export       string
	Standard     bool
	Root         string
	Incomplete   bool
	Match        []string
	Error        *GoListError
	Errors       []GoListError
	DepsErrors   []GoListError
}

type GoListError struct {
	ImportStack []string
	Pos         string
	Err         string
}

// Package holds the loaded package data.
type Package struct {
	importPath string
	fset       *token.FileSet
	files      []*ast.File
	typesInfo  *types.Info
	pkg        *types.Package
	hasErrors  bool
	errors     []string
}

// isTestVariant returns true if importPath is a test variant (contains "[")
func isTestVariant(importPath string) bool {
	return strings.Contains(importPath, "[")
}

// baseImportPath returns the base package path (without test variant suffix)
func baseImportPath(importPath string) string {
	idx := strings.Index(importPath, " [")
	if idx >= 0 {
		return importPath[:idx]
	}
	return importPath
}

// loadPackages loads packages using go list and parses/type-checks them.
func loadPackages(patterns []string, includeTests bool) ([]*Package, error) {
	args := []string{"list", "-json", "-e", "-export", "-deps"}
	if includeTests {
		args = append(args, "-test")
	}
	args = append(args, patterns...)

	cmd := exec.Command("go", args...)
	var stderrBuf strings.Builder
	cmd.Stderr = &stderrBuf
	out, _ := cmd.Output()

	// Parse all packages from go list output
	allPkgs := make(map[string]*GoListPackage)
	var orderedPkgs []string // all pkgs in order

	dec := json.NewDecoder(strings.NewReader(string(out)))
	for {
		var pkg GoListPackage
		if err := dec.Decode(&pkg); err != nil {
			break
		}
		if _, exists := allPkgs[pkg.ImportPath]; !exists {
			allPkgs[pkg.ImportPath] = &pkg
			orderedPkgs = append(orderedPkgs, pkg.ImportPath)
		}
	}

	// Build export map for importer
	exportMap := make(map[string]string)
	for path, pkg := range allPkgs {
		if pkg.Export != "" {
			exportMap[path] = pkg.Export
		}
	}

	// Determine which packages to analyze
	// When includeTests=true, we want:
	// - Test-augmented variants (pkg [pkg.test]) for analysis
	// - Test binary packages (pkg.test) for error reporting
	// When includeTests=false:
	// - Regular packages only (no test variants)

	// Collect matched packages (in order they appear in go list output)
	var matchedPkgs []string
	testVariantFor := make(map[string]string) // base path -> test variant path
	testBinaryPkgs := make(map[string]*GoListPackage) // ".test" packages

	for _, importPath := range orderedPkgs {
		pkg := allPkgs[importPath]
		if len(pkg.Match) == 0 || pkg.Standard {
			// Check if this is a .test binary package with errors
			if includeTests && strings.HasSuffix(importPath, ".test") {
				base := importPath[:len(importPath)-5] // remove ".test"
				testBinaryPkgs[base] = pkg
			}
			continue
		}

		if isTestVariant(importPath) {
			// This is a test-augmented package
			base := baseImportPath(importPath)
			testVariantFor[base] = importPath
		}

		found := false
		for _, m := range matchedPkgs {
			if m == importPath {
				found = true
				break
			}
		}
		if !found {
			matchedPkgs = append(matchedPkgs, importPath)
		}
	}

	// When includeTests=true, replace regular packages with test variants
	if includeTests {
		for i, importPath := range matchedPkgs {
			if !isTestVariant(importPath) {
				if testVariant, ok := testVariantFor[importPath]; ok {
					matchedPkgs[i] = testVariant
				}
			}
		}
		// Remove duplicate test variants
		seen := make(map[string]bool)
		var uniqueMatched []string
		for _, p := range matchedPkgs {
			if !seen[p] {
				seen[p] = true
				uniqueMatched = append(uniqueMatched, p)
			}
		}
		matchedPkgs = uniqueMatched
	}

	var result []*Package

	for _, importPath := range matchedPkgs {
		listPkg := allPkgs[importPath]
		if listPkg == nil {
			continue
		}

		// Check if the package has a go list error
		var goListErrors []string
		if listPkg.Error != nil {
			goListErrors = append(goListErrors, listPkg.Error.Err)
		}
		for _, e := range listPkg.Errors {
			goListErrors = append(goListErrors, e.Err)
		}

		// Also check for .test binary errors if this is a test variant
		if includeTests && isTestVariant(importPath) {
			base := baseImportPath(importPath)
			if testBinPkg, ok := testBinaryPkgs[base]; ok && testBinPkg.Error != nil {
				goListErrors = append(goListErrors, testBinPkg.Error.Err)
			}
		}

		// Handle packages with no Go files (pure error case)
		if listPkg.Incomplete && len(listPkg.GoFiles) == 0 {
			result = append(result, &Package{
				importPath: importPath,
				hasErrors:  true,
				errors:     goListErrors,
			})
			continue
		}

		// Use GoFiles as-is (test-augmented packages already include test files)
		goFiles := append([]string{}, listPkg.GoFiles...)

		if len(goFiles) == 0 {
			continue
		}

		pkg, err := loadPackage(listPkg, goFiles, exportMap, goListErrors)
		if err != nil {
			result = append(result, &Package{
				importPath: importPath,
				hasErrors:  true,
				errors:     append(goListErrors, fmt.Sprintf("%s: %v", importPath, err)),
			})
			continue
		}
		result = append(result, pkg)
	}

	return result, nil
}

func loadPackage(listPkg *GoListPackage, goFiles []string, exportMap map[string]string, goListErrors []string) (*Package, error) {
	fset := token.NewFileSet()
	var files []*ast.File
	var typeErrors []string
	var hasTypeErrors bool

	lookup := func(path string) (io.ReadCloser, error) {
		if exportFile, ok := exportMap[path]; ok {
			return os.Open(exportFile)
		}
