			Files:     pkg.files,
			TypesInfo: pkg.typesInfo,
			Pkg:       pkg.pkg,
		}
		analyzer.Run()

		if len(analyzer.Diagnostics) > 0 {
			exitCode = 1
		}

		if *jsonOutput {
			diags := make([]JSONDiagnostic, 0, len(analyzer.Diagnostics))
			for _, d := range analyzer.Diagnostics {
				diags = append(diags, JSONDiagnostic{
					Posn:    d.Pos.String(),
					Message: d.Message,
				})
			}
			if len(diags) > 0 {
				if jsonTree[pkg.importPath] == nil {
					jsonTree[pkg.importPath] = make(map[string]interface{})
				}
				jsonTree[pkg.importPath][analyzerName] = diags
			}
		} else {
			for _, d := range analyzer.Diagnostics {
				fmt.Fprintf(os.Stderr, "%s: %s\n", d.Pos, d.Message)
				if *contextN >= 0 {
					printContext(d.Pos, *contextN)
				}
			}
		}
	}

	if *jsonOutput && len(jsonTree) > 0 {
		data, err := json.MarshalIndent(jsonTree, "", "\t")
		if err != nil {
			log.Printf("json marshal error: %v", err)
		} else {
			fmt.Printf("%s\n", data)
		}
	}

	os.Exit(exitCode)
}

// printPackageErrorLines prints the error lines for a failed package.
func printPackageErrorLines(pkg *Package) {
	if len(pkg.errors) == 0 {
		return
	}

	firstLine := true
	for _, e := range pkg.errors {
		lines := strings.Split(strings.TrimRight(e, "\n"), "\n")
		for _, line := range lines {
			if line == "" {
				continue
			}
			if firstLine {
				fmt.Fprintf(os.Stderr, "-: %s\n", line)
				firstLine = false
			} else {
				fmt.Fprintf(os.Stderr, "%s\n", line)
			}
		}
	}
}

func printContext(pos token.Position, n int) {
	data, err := os.ReadFile(pos.Filename)
	if err != nil {
		return
	}
	lines := strings.Split(string(data), "\n")
	start := pos.Line - n
	end := pos.Line + n
	for i := start; i <= end; i++ {
		if 1 <= i && i <= len(lines) {
			fmt.Fprintf(os.Stderr, "%d\t%s\n", i, lines[i-1])
		}
	}
}

