// loadPackages loads packages using go list and parses/type-checks them.
func loadPackages(patterns []string, includeTests bool) ([]*Package, error) {
	args := []string{"list", "-json", "-e", "-export", "-deps"}
	if includeTests {
		args = append(args, "-test")
	}
	args = append(args, patterns...)

	cmd := exec.Command("go", args...)
	var stderrBuf strings.Builder
	cmd.Stderr = &stderrBuf
	out, _ := cmd.Output()

	// Parse all packages from go list output
	allPkgs := make(map[string]*GoListPackage)
	var orderedPkgs []string // all pkgs in order

	dec := json.NewDecoder(strings.NewReader(string(out)))
	for {
		var pkg GoListPackage
		if err := dec.Decode(&pkg); err != nil {
			break
		}
		if _, exists := allPkgs[pkg.ImportPath]; !exists {
			allPkgs[pkg.ImportPath] = &pkg
			orderedPkgs = append(orderedPkgs, pkg.ImportPath)
		}
	}

	// Build export map for importer
	exportMap := make(map[string]string)
	for path, pkg := range allPkgs {
		if pkg.Export != "" {
			exportMap[path] = pkg.Export
		}
	}

	// Determine which packages to analyze
	// When includeTests=true, we want:
	// - Test-augmented variants (pkg [pkg.test]) for analysis
	// - Test binary packages (pkg.test) for error reporting
	// When includeTests=false:
	// - Regular packages only (no test variants)

	// Collect matched packages (in order they appear in go list output)
	var matchedPkgs []string
	testVariantFor := make(map[string]string) // base path -> test variant path
	testBinaryPkgs := make(map[string]*GoListPackage) // ".test" packages

	for _, importPath := range orderedPkgs {
		pkg := allPkgs[importPath]
		if len(pkg.Match) == 0 || pkg.Standard {
			// Check if this is a .test binary package with errors
			if includeTests && strings.HasSuffix(importPath, ".test") {
				base := importPath[:len(importPath)-5] // remove ".test"
				testBinaryPkgs[base] = pkg
			}
			continue
		}

		if isTestVariant(importPath) {
			// This is a test-augmented package
			base := baseImportPath(importPath)
			testVariantFor[base] = importPath
		}

		found := false
		for _, m := range matchedPkgs {
			if m == importPath {
				found = true
				break
			}
		}
		if !found {
			matchedPkgs = append(matchedPkgs, importPath)
		}
	}

	// When includeTests=true, replace regular packages with test variants
	if includeTests {
		for i, importPath := range matchedPkgs {
			if !isTestVariant(importPath) {
				if testVariant, ok := testVariantFor[importPath]; ok {
					matchedPkgs[i] = testVariant
				}
			}
		}
		// Remove duplicate test variants
		seen := make(map[string]bool)
		var uniqueMatched []string
		for _, p := range matchedPkgs {
			if !seen[p] {
				seen[p] = true
				uniqueMatched = append(uniqueMatched, p)
			}
		}
		matchedPkgs = uniqueMatched
	}

	var result []*Package

	for _, importPath := range matchedPkgs {
		listPkg := allPkgs[importPath]
		if listPkg == nil {
			continue
		}

		// Check if the package has a go list error
		var goListErrors []string
		if listPkg.Error != nil {
			goListErrors = append(goListErrors, listPkg.Error.Err)
		}
		for _, e := range listPkg.Errors {
			goListErrors = append(goListErrors, e.Err)
		}

		// Also check for .test binary errors if this is a test variant
		if includeTests && isTestVariant(importPath) {
			base := baseImportPath(importPath)
			if testBinPkg, ok := testBinaryPkgs[base]; ok && testBinPkg.Error != nil {
				goListErrors = append(goListErrors, testBinPkg.Error.Err)
			}
		}

		// Handle packages with no Go files (pure error case)
		if listPkg.Incomplete && len(listPkg.GoFiles) == 0 {
			result = append(result, &Package{
				importPath: importPath,
				hasErrors:  true,
				errors:     goListErrors,
			})
			continue
		}

		// Use GoFiles as-is (test-augmented packages already include test files)
		goFiles := append([]string{}, listPkg.GoFiles...)

		if len(goFiles) == 0 {
			continue
		}

		pkg, err := loadPackage(listPkg, goFiles, exportMap, goListErrors)
		if err != nil {
			result = append(result, &Package{
				importPath: importPath,
				hasErrors:  true,
				errors:     append(goListErrors, fmt.Sprintf("%s: %v", importPath, err)),
			})
			continue
		}
		result = append(result, pkg)
	}

	return result, nil
}

func loadPackage(listPkg *GoListPackage, goFiles []string, exportMap map[string]string, goListErrors []string) (*Package, error) {
	fset := token.NewFileSet()
	var files []*ast.File
	var typeErrors []string
	var hasTypeErrors bool

	lookup := func(path string) (io.ReadCloser, error) {
		if exportFile, ok := exportMap[path]; ok {
			return os.Open(exportFile)
		}
		return nil, fmt.Errorf("no export data for %s", path)
	}

	typeCfg := &types.Config{
		Importer: importer.ForCompiler(fset, "gc", lookup),
		Error: func(err error) {
			typeErrors = append(typeErrors, err.Error())
			hasTypeErrors = true
		},
	}

	var parseErrors []string
	hasParseErrors := false
	for _, f := range goFiles {
		var filePath string
		if filepath.IsAbs(f) {
			filePath = f
		} else {
			filePath = filepath.Join(listPkg.Dir, f)
		}

		astFile, err := parser.ParseFile(fset, filePath, nil, 0)
		if err != nil {
			parseErrors = append(parseErrors, fmt.Sprintf("%s: %v", filePath, err))
			hasParseErrors = true
			if astFile != nil {
				files = append(files, astFile)
			}
			continue
		}
		files = append(files, astFile)
	}

	// Use the base import path for type checking (without test variant suffix)
	checkPath := baseImportPath(listPkg.ImportPath)

	info := &types.Info{
		Types: make(map[ast.Expr]types.TypeAndValue),
		Defs:  make(map[*ast.Ident]types.Object),
		Uses:  make(map[*ast.Ident]types.Object),
	}

	_, _ = typeCfg.Check(checkPath, fset, files, info)

	allErrors := append([]string{}, goListErrors...)
	allErrors = append(allErrors, parseErrors...)
	allErrors = append(allErrors, typeErrors...)

	if len(allErrors) > 0 || hasParseErrors || hasTypeErrors {
		return &Package{
			importPath: checkPath,
			hasErrors:  true,
			errors:     allErrors,
		}, nil
	}

	return &Package{
		importPath: checkPath,
		fset:       fset,
		files:      files,
		typesInfo:  info,
		pkg:        nil,
	}, nil
}

