package main

import (
	"crypto/sha256"
	"encoding/json"
	"flag"
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/token"
	"go/types"
	"io"
	"log"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/tomarrell/wrapcheck/v2/wrapcheck"
)

var (
	jsonOutput = flag.Bool("json", false, "emit JSON output")
	contextN   = flag.Int("c", -1, "display offending line with this many lines of context")
	testFiles  = flag.Bool("test", true, "indicates whether test files should be analyzed, too")
	_          = flag.Bool("all", false, "no effect (deprecated)")
	_          = flag.Bool("source", false, "no effect (deprecated)")
	_          = flag.Bool("v", false, "no effect (deprecated)")
	_          = flag.String("tags", "", "no effect (deprecated)")
	_          = flag.String("cpuprofile", "", "write CPU profile to this file")
	_          = flag.String("memprofile", "", "write memory profile to this file")
	_          = flag.String("debug", "", `debug flags, any subset of "fpstv"`)
	_          = flag.String("trace", "", "write trace log to this file")
	_          = flag.Bool("diff", false, "with -fix, don't update the files, but print a unified diff")
	_          = flag.Bool("fix", false, "apply all suggested fixes")
)

const analyzerName = "wrapcheck"
const analyzerDoc = "Checks that errors returned from external packages are wrapped"

func init() {
	flag.Var(&versionFlag{}, "V", "print version and exit")
	flag.Bool("flags", false, "print analyzer flags in JSON")
}

func main() {
	log.SetFlags(0)
	log.SetPrefix(analyzerName + ": ")

	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, "%s: %s\n\nUsage: %s [-flag] [package]\n\n\nFlags:\n", analyzerName, analyzerDoc, analyzerName)
		flag.PrintDefaults()
	}

	flag.Parse()

	if f := flag.Lookup("flags"); f != nil && f.Value.String() == "true" {
		printAnalyzerFlags()
		os.Exit(0)
	}

	args := flag.Args()
	if len(args) == 0 {
		flag.Usage()
		os.Exit(1)
	}

	cwd, err := os.Getwd()
	if err != nil {
		cwd = "."
	}
	cfg, err := wrapcheck.LoadConfig(cwd)
	if err != nil {
		log.Printf("error loading config: %v", err)
	}

	pkgs, err := loadPackages(args, *testFiles)
	if err != nil {
		log.Printf("failed to load packages: %v", err)
		os.Exit(1)
	}

	exitCode := 0
	jsonTree := make(JSONTree)

	var errorPkgs []*Package
	var validPkgs []*Package
	for _, pkg := range pkgs {
		if pkg.hasErrors {
			errorPkgs = append(errorPkgs, pkg)
		} else {
			validPkgs = append(validPkgs, pkg)
		}
	}

	// Phase 1: Print error messages
	for _, pkg := range errorPkgs {
		printPackageErrorLines(pkg)
	}

	// Phase 2: Print "analysis skipped"
	for range errorPkgs {
		fmt.Fprintf(os.Stderr, "%s: analysis skipped due to errors in package\n", analyzerName)
		exitCode = 1
	}

	// Diagnostics tracker for non-json mode (deduplication)
	type diagKey struct {
		file string
		line int
		col  int
	}
	seenDiags := make(map[diagKey]bool)

	// Phase 3: Analyze valid packages
	for _, pkg := range validPkgs {
		// Use base path for analysis (without test variant suffix)
		pkgPath := baseImportPath(pkg.importPath)

		analyzer := &wrapcheck.Analyzer{
			Config:    cfg,
			PkgPath:   pkgPath,
			Fset:      pkg.fset,
			Files:     pkg.files,
			TypesInfo: pkg.typesInfo,
			Pkg:       pkg.pkg,
		}
		analyzer.Run()

		if len(analyzer.Diagnostics) > 0 {
			exitCode = 1
		}

		if *jsonOutput {
			diags := make([]JSONDiagnostic, 0, len(analyzer.Diagnostics))
			for _, d := range analyzer.Diagnostics {
				diags = append(diags, JSONDiagnostic{
					Posn:    d.Pos.String(),
					Message: d.Message,
				})
			}
			if len(diags) > 0 {
				if jsonTree[pkg.importPath] == nil {
					jsonTree[pkg.importPath] = make(map[string]interface{})
				}
				jsonTree[pkg.importPath][analyzerName] = diags
			}
		} else {
			for _, d := range analyzer.Diagnostics {
				key := diagKey{d.Pos.Filename, d.Pos.Line, d.Pos.Column}
				if seenDiags[key] {
					continue
				}
				seenDiags[key] = true
				fmt.Fprintf(os.Stderr, "%s: %s\n", d.Pos, d.Message)
				if *contextN >= 0 {
					printContext(d.Pos, *contextN)
				}
			}
		}
	}

	if *jsonOutput && len(jsonTree) > 0 {
		data, err := json.MarshalIndent(jsonTree, "", "\t")
		if err != nil {
			log.Printf("json marshal error: %v", err)
		} else {
			fmt.Printf("%s\n", data)
		}
	}

	os.Exit(exitCode)
}

func printPackageErrorLines(pkg *Package) {
	if len(pkg.errors) == 0 {
		return
	}
	firstLine := true
	for _, e := range pkg.errors {
		lines := strings.Split(strings.TrimRight(e, "\n"), "\n")
		for _, line := range lines {
			if line == "" {
				continue
			}
			if firstLine {
				fmt.Fprintf(os.Stderr, "-: %s\n", line)
				firstLine = false
			} else {
				fmt.Fprintf(os.Stderr, "%s\n", line)
			}
		}
	}
}

func printContext(pos token.Position, n int) {
	data, err := os.ReadFile(pos.Filename)
	if err != nil {
		return
	}
	lines := strings.Split(string(data), "\n")
	start := pos.Line - n
	end := pos.Line + n
	for i := start; i <= end; i++ {
		if 1 <= i && i <= len(lines) {
			fmt.Fprintf(os.Stderr, "%d\t%s\n", i, lines[i-1])
		}
	}
}

type GoListPackage struct {
	Dir          string
	ImportPath   string
	Name         string
	GoFiles      []string
	TestGoFiles  []string
	XTestGoFiles []string
	CgoFiles     []string
	Export       string
	Standard     bool
	Root         string
	Incomplete   bool
	Match        []string
	Error        *GoListError
	Errors       []GoListError
	DepsErrors   []GoListError
}

type GoListError struct {
	ImportStack []string
	Pos         string
	Err         string
}

type Package struct {
	importPath string // may include "[...]" for test variants
	fset       *token.FileSet
	files      []*ast.File
	typesInfo  *types.Info
	pkg        *types.Package
	hasErrors  bool
	errors     []string
}

func isTestVariant(importPath string) bool {
	return strings.Contains(importPath, " [")
}

func baseImportPath(importPath string) string {
	idx := strings.Index(importPath, " [")
	if idx >= 0 {
		return importPath[:idx]
	}
	return importPath
}

func isTestBinary(importPath string) bool {
	return strings.HasSuffix(importPath, ".test")
}

func loadPackages(patterns []string, includeTests bool) ([]*Package, error) {
	args := []string{"list", "-json", "-e", "-export", "-deps"}
	if includeTests {
		args = append(args, "-test")
	}
	args = append(args, patterns...)

	cmd := exec.Command("go", args...)
	var stderrBuf strings.Builder
	cmd.Stderr = &stderrBuf
	out, _ := cmd.Output()

	allPkgs := make(map[string]*GoListPackage)
	var orderedPkgs []string

	dec := json.NewDecoder(strings.NewReader(string(out)))
	for {
		var pkg GoListPackage
		if err := dec.Decode(&pkg); err != nil {
			break
		}
		if _, exists := allPkgs[pkg.ImportPath]; !exists {
			allPkgs[pkg.ImportPath] = &pkg
			orderedPkgs = append(orderedPkgs, pkg.ImportPath)
		}
	}

	exportMap := make(map[string]string)
	for path, pkg := range allPkgs {
		if pkg.Export != "" {
			exportMap[path] = pkg.Export
		}
	}

	// Collect matched packages in order, handling test variants
	// When includeTests=true, we want BOTH regular AND test variants
	// plus error packages from .test binaries

	var result []*Package

	// Track which regular packages have been processed
	processedBase := make(map[string]bool)

	// Process in order as returned by go list
	for _, importPath := range orderedPkgs {
		pkg := allPkgs[importPath]
		if pkg.Standard {
			continue
		}

		if len(pkg.Match) == 0 {
			// Not a matched package
			// But if it's a .test binary with errors, we still want to report it
			if includeTests && isTestBinary(importPath) && pkg.Incomplete && pkg.Error != nil {
				// Find the base path (remove .test suffix)
				base := importPath[:len(importPath)-5]
				// Add as error package
				result = append(result, &Package{
					importPath: base,
					hasErrors:  true,
					errors:     []string{pkg.Error.Err},
				})
			}
			continue
		}

		// This is a matched package
		if isTestVariant(importPath) {
			// Test-augmented variant
			base := baseImportPath(importPath)
			processedBase[base] = true

			goFiles := append([]string{}, pkg.GoFiles...)
			if len(goFiles) == 0 {
				continue
			}

			var goListErrors []string
			if pkg.Error != nil {
				goListErrors = append(goListErrors, pkg.Error.Err)
			}

			loaded, err := loadPackage(pkg, goFiles, exportMap, goListErrors)
			if err != nil {
				result = append(result, &Package{
					importPath: importPath,
					hasErrors:  true,
					errors:     append(goListErrors, err.Error()),
				})
			} else {
				loaded.importPath = importPath // preserve the full path for JSON key
				result = append(result, loaded)
			}
		} else if isTestBinary(importPath) {
			// Test binary package (.test) - error package
			if pkg.Incomplete && pkg.Error != nil {
				base := importPath[:len(importPath)-5]
				result = append(result, &Package{
					importPath: base,
					hasErrors:  true,
					errors:     []string{pkg.Error.Err},
				})
			}
		} else {
			// Regular (non-test) matched package
			if includeTests && processedBase[importPath] {
				// Already processed as test variant, add regular one too for JSON
				goFiles := append([]string{}, pkg.GoFiles...)
				if len(goFiles) == 0 {
					continue
				}

				var goListErrors []string
				if pkg.Error != nil {
					goListErrors = append(goListErrors, pkg.Error.Err)
				}

				if pkg.Incomplete && len(goFiles) == 0 {
					result = append(result, &Package{
						importPath: importPath,
						hasErrors:  true,
						errors:     goListErrors,
					})
					continue
				}

				loaded, err := loadPackage(pkg, goFiles, exportMap, goListErrors)
				if err != nil {
					result = append(result, &Package{
						importPath: importPath,
						hasErrors:  true,
						errors:     append(goListErrors, err.Error()),
					})
				} else {
					loaded.importPath = importPath
					result = append(result, loaded)
				}
			} else if !includeTests || !processedBase[importPath] {
				// Process this package normally
				var goListErrors []string
				if pkg.Error != nil {
					goListErrors = append(goListErrors, pkg.Error.Err)
				}
				for _, e := range pkg.Errors {
					goListErrors = append(goListErrors, e.Err)
				}

				if pkg.Incomplete && len(pkg.GoFiles) == 0 {
					result = append(result, &Package{
						importPath: importPath,
						hasErrors:  true,
						errors:     goListErrors,
					})
					continue
				}

				goFiles := append([]string{}, pkg.GoFiles...)
				if !includeTests {
					// Don't add test files (use only GoFiles from the package)
				}

				if len(goFiles) == 0 {
					continue
				}

				loaded, err := loadPackage(pkg, goFiles, exportMap, goListErrors)
				if err != nil {
					result = append(result, &Package{
						importPath: importPath,
						hasErrors:  true,
						errors:     append(goListErrors, err.Error()),
					})
				} else {
					loaded.importPath = importPath
					result = append(result, loaded)
				}
			}
		}
	}

	return result, nil
}

func loadPackage(listPkg *GoListPackage, goFiles []string, exportMap map[string]string, goListErrors []string) (*Package, error) {
	fset := token.NewFileSet()
	var files []*ast.File
	var typeErrors []string
	var hasTypeErrors bool

	lookup := func(path string) (io.ReadCloser, error) {
		if exportFile, ok := exportMap[path]; ok {
			return os.Open(exportFile)
		}
		return nil, fmt.Errorf("no export data for %s", path)
	}

	typeCfg := &types.Config{
		Importer: importer.ForCompiler(fset, "gc", lookup),
		Error: func(err error) {
			typeErrors = append(typeErrors, err.Error())
			hasTypeErrors = true
		},
	}

	var parseErrors []string
	hasParseErrors := false
	for _, f := range goFiles {
		var filePath string
		if filepath.IsAbs(f) {
			filePath = f
		} else {
			filePath = filepath.Join(listPkg.Dir, f)
		}

		astFile, err := parser.ParseFile(fset, filePath, nil, 0)
		if err != nil {
			parseErrors = append(parseErrors, fmt.Sprintf("%s: %v", filePath, err))
			hasParseErrors = true
			if astFile != nil {
				files = append(files, astFile)
			}
			continue
		}
		files = append(files, astFile)
	}

	checkPath := baseImportPath(listPkg.ImportPath)

	info := &types.Info{
		Types: make(map[ast.Expr]types.TypeAndValue),
		Defs:  make(map[*ast.Ident]types.Object),
		Uses:  make(map[*ast.Ident]types.Object),
	}

	_, _ = typeCfg.Check(checkPath, fset, files, info)

	allErrors := append([]string{}, goListErrors...)
	allErrors = append(allErrors, parseErrors...)
	allErrors = append(allErrors, typeErrors...)

	if len(allErrors) > 0 || hasParseErrors || hasTypeErrors {
		return &Package{
			importPath: listPkg.ImportPath,
			hasErrors:  true,
			errors:     allErrors,
		}, nil
	}

	return &Package{
		importPath: listPkg.ImportPath,
		fset:       fset,
		files:      files,
		typesInfo:  info,
		pkg:        nil,
	}, nil
}

type JSONTree map[string]map[string]interface{}

type JSONDiagnostic struct {
	Posn    string `json:"posn"`
	Message string `json:"message"`
}

func printAnalyzerFlags() {
	type flagInfo struct {
		Name  string `json:"Name"`
		Bool  bool   `json:"Bool"`
		Usage string `json:"Usage"`
	}

	flags := []flagInfo{
		{Name: "V", Bool: true, Usage: "print version and exit"},
		{Name: "all", Bool: true, Usage: "no effect (deprecated)"},
		{Name: "c", Bool: false, Usage: "display offending line with this many lines of context"},
		{Name: "diff", Bool: true, Usage: "with -fix, don't update the files, but print a unified diff"},
		{Name: "flags", Bool: true, Usage: "print analyzer flags in JSON"},
		{Name: "json", Bool: true, Usage: "emit JSON output"},
		{Name: "source", Bool: true, Usage: "no effect (deprecated)"},
		{Name: "tags", Bool: false, Usage: "no effect (deprecated)"},
		{Name: "test", Bool: true, Usage: "indicates whether test files should be analyzed, too"},
		{Name: "v", Bool: true, Usage: "no effect (deprecated)"},
	}

	data, _ := json.MarshalIndent(flags, "", "\t")
	fmt.Printf("%s", data)
}

type versionFlag struct{}

func (versionFlag) IsBoolFlag() bool { return true }
func (versionFlag) Get() interface{} { return nil }
func (versionFlag) String() string   { return "" }
func (versionFlag) Set(s string) error {
	if s != "full" {
		log.Fatalf("unsupported flag value: -V=%s (use -V=full)", s)
	}

	progname, err := os.Executable()
	if err != nil {
