	"go/parser"
	"go/token"
	"go/types"
	"io"
	"log"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/tomarrell/wrapcheck/v2/wrapcheck"
)

var (
	jsonOutput = flag.Bool("json", false, "emit JSON output")
	contextN   = flag.Int("c", -1, "display offending line with this many lines of context")
	testFiles  = flag.Bool("test", true, "indicates whether test files should be analyzed, too")
	_          = flag.Bool("all", false, "no effect (deprecated)")
	_          = flag.Bool("source", false, "no effect (deprecated)")
	_          = flag.Bool("v", false, "no effect (deprecated)")
	_          = flag.String("tags", "", "no effect (deprecated)")
	_          = flag.String("cpuprofile", "", "write CPU profile to this file")
	_          = flag.String("memprofile", "", "write memory profile to this file")
	_          = flag.String("debug", "", `debug flags, any subset of "fpstv"`)
	_          = flag.String("trace", "", "write trace log to this file")
	_          = flag.Bool("diff", false, "with -fix, don't update the files, but print a unified diff")
	_          = flag.Bool("fix", false, "apply all suggested fixes")
)

const analyzerName = "wrapcheck"
const analyzerDoc = "Checks that errors returned from external packages are wrapped"

func init() {
	flag.Var(&versionFlag{}, "V", "print version and exit")
	flag.Bool("flags", false, "print analyzer flags in JSON")
}

func main() {
	log.SetFlags(0)
	log.SetPrefix(analyzerName + ": ")

	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, "%s: %s\n\nUsage: %s [-flag] [package]\n\n\nFlags:\n", analyzerName, analyzerDoc, analyzerName)
		flag.PrintDefaults()
	}

	flag.Parse()

	if f := flag.Lookup("flags"); f != nil && f.Value.String() == "true" {
		printAnalyzerFlags()
		os.Exit(0)
	}

	args := flag.Args()
	if len(args) == 0 {
		flag.Usage()
		os.Exit(1)
	}

