	jsonTree := make(JSONTree)

	// Separate error packages from valid packages
	var errorPkgs []*Package
	var validPkgs []*Package
	for _, pkg := range pkgs {
		if pkg.hasErrors {
			errorPkgs = append(errorPkgs, pkg)
		} else {
			validPkgs = append(validPkgs, pkg)
		}
	}

