			for _, d := range analyzer.Diagnostics {
				key := diagKey{d.Pos.Filename, d.Pos.Line, d.Pos.Column}
				if seenDiags[key] {
					continue
				}
				seenDiags[key] = true
				fmt.Fprintf(os.Stderr, "%s: %s\n", d.Pos, d.Message)
				if *contextN >= 0 {
					printContext(d.Pos, *contextN)
				}
