func printContext(pos token.Position, n int) {
	data, err := os.ReadFile(pos.Filename)
	if err != nil {
		return
	}
	lines := strings.Split(string(data), "\n")
	start := pos.Line - n
	end := pos.Line + n
	for i := start; i <= end; i++ {
		if 1 <= i && i <= len(lines) {
			fmt.Fprintf(os.Stderr, "%d\t%s\n", i, lines[i-1])
		}
	}
}

type GoListPackage struct {
	Dir          string
	ImportPath   string
	Name         string
	GoFiles      []string
	TestGoFiles  []string
	XTestGoFiles []string
	CgoFiles     []string
	Export       string
	Standard     bool
	Root         string
	Incomplete   bool
	Match        []string
	Error        *GoListError
	Errors       []GoListError
	DepsErrors   []GoListError
}

type GoListError struct {
	ImportStack []string
	Pos         string
	Err         string
}

type Package struct {
	importPath string
	fset       *token.FileSet
	files      []*ast.File
	typesInfo  *types.Info
	pkg        *types.Package
	hasErrors  bool
	errors     []string
}

func isTestVariant(importPath string) bool {
	return strings.Contains(importPath, " [")
}

func baseImportPath(importPath string) string {
	idx := strings.Index(importPath, " [")
	if idx >= 0 {
		return importPath[:idx]
	}
	return importPath
}

func isTestBinary(importPath string) bool {
	return strings.HasSuffix(importPath, ".test")
}

func loadPackages(patterns []string, includeTests bool) ([]*Package, error) {
	args := []string{"list", "-json", "-e", "-export", "-deps"}
	if includeTests {
		args = append(args, "-test")
	}
	args = append(args, patterns...)

	cmd := exec.Command("go", args...)
	var stderrBuf strings.Builder
	cmd.Stderr = &stderrBuf
	out, _ := cmd.Output()

	allPkgs := make(map[string]*GoListPackage)
	var orderedPkgs []string

	dec := json.NewDecoder(strings.NewReader(string(out)))
	for {
		var pkg GoListPackage
		if err := dec.Decode(&pkg); err != nil {
			break
		}
		if _, exists := allPkgs[pkg.ImportPath]; !exists {
			allPkgs[pkg.ImportPath] = &pkg
			orderedPkgs = append(orderedPkgs, pkg.ImportPath)
		}
	}

	exportMap := make(map[string]string)
	for path, pkg := range allPkgs {
		if pkg.Export != "" {
			exportMap[path] = pkg.Export
		}
	}

	var result []*Package

	for _, importPath := range orderedPkgs {
		pkg := allPkgs[importPath]
		if pkg.Standard {
			continue
		}

		if len(pkg.Match) == 0 {
			// Not a matched package - check for .test binary errors
			if includeTests && isTestBinary(importPath) && pkg.Incomplete && pkg.Error != nil {
				result = append(result, &Package{
					importPath: importPath,
					hasErrors:  true,
					errors:     []string{pkg.Error.Err},
				})
			}
			continue
		}

		// This is a matched package
		var goListErrors []string
		if pkg.Error != nil {
			goListErrors = append(goListErrors, pkg.Error.Err)
		}
		for _, e := range pkg.Errors {
			goListErrors = append(goListErrors, e.Err)
		}

		// Handle packages with no Go files (pure error case)
		if pkg.Incomplete && len(pkg.GoFiles) == 0 {
			result = append(result, &Package{
				importPath: importPath,
				hasErrors:  true,
				errors:     goListErrors,
			})
			continue
		}

		// Use GoFiles as provided by go list
		// For test variants, GoFiles already includes test files
		// For regular packages, GoFiles is just the regular files
		goFiles := append([]string{}, pkg.GoFiles...)

		if len(goFiles) == 0 {
			continue
		}

		loaded, err := loadPackage(pkg, goFiles, exportMap, goListErrors)
		if err != nil {
			result = append(result, &Package{
				importPath: importPath,
				hasErrors:  true,
				errors:     append(goListErrors, err.Error()),
			})
		} else {
			loaded.importPath = importPath
			result = append(result, loaded)
		}
	}

	return result, nil
}

func loadPackage(listPkg *GoListPackage, goFiles []string, exportMap map[string]string, goListErrors []string) (*Package, error) {
	fset := token.NewFileSet()
	var files []*ast.File
	var typeErrors []string
	var hasTypeErrors bool

	lookup := func(path string) (io.ReadCloser, error) {
		if exportFile, ok := exportMap[path]; ok {
			return os.Open(exportFile)
		}
		return nil, fmt.Errorf("no export data for %s", path)
	}

	typeCfg := &types.Config{
		Importer: importer.ForCompiler(fset, "gc", lookup),
		Error: func(err error) {
			typeErrors = append(typeErrors, err.Error())
			hasTypeErrors = true
		},
	}

	var parseErrors []string
	hasParseErrors := false
	for _, f := range goFiles {
		var filePath string
		if filepath.IsAbs(f) {
			filePath = f
		} else {
			filePath = filepath.Join(listPkg.Dir, f)
		}

		astFile, err := parser.ParseFile(fset, filePath, nil, 0)
		if err != nil {
			parseErrors = append(parseErrors, fmt.Sprintf("%s: %v", filePath, err))
			hasParseErrors = true
			if astFile != nil {
				files = append(files, astFile)
			}
			continue
		}
		files = append(files, astFile)
	}

	checkPath := baseImportPath(listPkg.ImportPath)

	info := &types.Info{
		Types: make(map[ast.Expr]types.TypeAndValue),
		Defs:  make(map[*ast.Ident]types.Object),
		Uses:  make(map[*ast.Ident]types.Object),
	}

	_, _ = typeCfg.Check(checkPath, fset, files, info)

	allErrors := append([]string{}, goListErrors...)
	allErrors = append(allErrors, parseErrors...)
	allErrors = append(allErrors, typeErrors...)

	if len(allErrors) > 0 || hasParseErrors || hasTypeErrors {
		return &Package{
			importPath: listPkg.ImportPath,
			hasErrors:  true,
			errors:     allErrors,
		}, nil
	}

	return &Package{
		importPath: listPkg.ImportPath,
		fset:       fset,
		files:      files,
		typesInfo:  info,
		pkg:        nil,
	}, nil
}

